(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_GENESIS_1_1_TO_2_3_WORBS_GEN001_20261015_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/창세기/JBC_GENESIS_1_1_TO_2_3_WORBS_GEN001_20261015_01.md","sourceSha256":"c26ccd75cf3382745b07c3c8786deec1662f87e4b80e0273f90bcce7b40dae5e","passage":{"book":"gen","chapter":1,"chapterEnd":2,"v1":1,"v2":3,"ref":"창세기 1:1–2:3"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"PASS_WITH_VERIFY","externalRelease":"NOT_AUTHORIZED","title":"창조의 일곱 날과 안식","overview":["하나님은 말씀으로 질서를 세우시고 세계를 생명으로 채우십니다. 남자와 여자 모두 하나님의 형상을 따라 지음 받아 복과 책임을 받으며, 창조는 일곱째 날에 완성되어 복되고 거룩한 쉼으로 끝납니다.","창세기 1장의 여섯 날과 2:1–3의 일곱째 날은 한 문학단락입니다. 2:4 이후의 에덴과 인간 관계 이야기는 다음 문학단락으로 분리됩니다."],"centralMessage":"하나님은 말씀으로 질서 있고 선한 세계를 세우시고 남자와 여자를 자신의 형상으로 부르시며, 창조를 완결하신 후 일곱째 날을 복되고 거룩하게 구별하십니다.","literaryStructure":[{"chapter":1,"v1":1,"v2":2,"title":"창조 선언과 초기 상태"},{"chapter":1,"v1":3,"v2":13,"title":"첫째~셋째 날: 구별과 터전"},{"chapter":1,"v1":14,"v2":23,"title":"넷째~다섯째 날: 역할과 번성"},{"chapter":1,"v1":24,"v2":31,"title":"여섯째 날: 형상과 복"},{"chapter":2,"v1":1,"v2":3,"title":"일곱째 날: 완결과 거룩한 쉼"}],"sections":[{"id":"gen001-1-1-2","v1":1,"v2":2,"title":"태초의 선언과 아직 채워지지 않은 세계","paragraphs":["성경은 창조주를 소개하는 계보나 그분의 기원을 설명하는 이야기로 시작하지 않습니다. ‘태초에 하나님이 천지를 창조하시니라’는 선언으로 출발합니다. 땅은 아직 정돈되고 채워진 세계가 아니며, 어둠과 깊음, 물의 이미지가 이어집니다. 이 배경 위에서 하나님의 말씀이 구별과 질서를 세웁니다.","‘창조하다’(בָּרָא)는 여기서 하나님이 하시는 행위를 가리키지만, 단어 자체만으로 ‘무에서의 창조’라는 철학적 진술 전체가 성립하는 것은 아닙니다. ‘태초에’의 문장 결합과 ‘하나님의 영/바람’의 번역에는 실제 논의가 있으므로 하나의 문법 가능성을 절대화하지 않습니다."]},{"id":"gen001-1-3-13","v1":3,"v2":13,"title":"첫째 날부터 셋째 날 — 구별과 생명의 터전","paragraphs":["하나님이 ‘빛이 있으라’ 말씀하시자 빛이 있습니다. 낮과 밤이 구별되고, 물 사이에 공간이 마련되며, 바다와 뭍이 제자리를 얻습니다. 셋째 날의 식물은 구별된 공간이 생명으로 채워지기 시작했음을 보여 줍니다.","창조의 이야기를 움직이는 것은 자연물 사이의 경쟁이나 신들의 전쟁이 아니라 하나님의 말씀입니다. 하나님은 만드신 것을 보시고 좋다고 평가하십니다. 이 반복은 세계가 하나님의 선한 판단 아래 있음을 서술합니다."]},{"id":"gen001-1-14-23","v1":14,"v2":23,"title":"넷째와 다섯째 날 — 빛을 맡는 광명체와 번성하는 생명","paragraphs":["넷째 날에는 하늘의 광명체가 낮과 밤을 구분하고 절기와 날과 해를 알리는 역할을 맡습니다. 광명체는 그 자체가 신적인 권위가 아니라 창조된 세계의 일부이며, 하나님이 정하신 기능 안에 놓여 있습니다.","다섯째 날에는 물속과 하늘의 생명이 등장합니다. 하나님은 그들에게 번성의 복을 주십니다. 첫 세 날과 뒤 세 날 사이의 영역 형성/채움 병행은 문학적으로 유익하지만, 모든 날의 내용을 기계적인 일대일 대응으로 환원해서는 안 됩니다."]},{"id":"gen001-1-24-31","v1":24,"v2":31,"title":"여섯째 날 — 하나님의 형상과 매우 좋은 세계","paragraphs":["육지의 생물들이 지어진 뒤, 사람의 창조에 서술의 무게가 실립니다. 하나님은 사람을 자신의 형상으로 창조하셨고, 본문은 ‘남자와 여자’를 함께 선언합니다. 형상과 복, 생육과 번성, 땅에 대한 책임이 두 사람 모두에게 주어집니다.","‘다스리라’는 명령은 실제 권한과 소명을 말합니다. 그러나 하나님이 창조를 ‘좋다’고 평가하신 문맥과 떼어내어 착취와 파괴의 무제한 허가로 읽기는 어렵습니다. 사람의 가치는 업적이 있기 전에 하나님의 창조 행위에서 선포됩니다.","1:26의 ‘우리’가 누구를 가리키는지는 다양한 해석이 있습니다. 기독교의 삼위일체 신앙과 정경적으로 연결해 성찰할 수 있지만, 복수 화법 하나가 곧바로 삼위일체 교리를 문법적으로 증명한다고 해서는 안 됩니다. 마지막에 하나님은 지으신 모든 것을 ‘심히 좋다’고 평가하십니다."]},{"id":"gen001-2-1-3","chapter":2,"v1":1,"v2":3,"title":"일곱째 날 — 완결된 창조와 복 받은 쉼","paragraphs":["이야기는 여섯째 날에서 끝나지 않습니다. 2:1–3에서 하늘과 땅과 그 모든 것이 완성되고 하나님은 하시던 일을 그치십니다. 일곱째 날을 복 주고 거룩하게 구별하신다는 진술은 창조의 마지막 장면에 특별한 무게를 둡니다.","‘쉬다’에 해당하는 שָׁבַת는 하나님이 지치셔서 기운을 회복하신다는 설명보다 일을 그치신다는 뜻을 부각합니다. 일곱째 날은 이후 출애굽기 20:8–11에서 이스라엘의 안식일과 연결되지만, 창세기 2:3 자체가 훗날의 모든 안식일 세칙을 이미 열거하는 것은 아닙니다.","2:4에서 ‘천지의 내력’이라는 새로운 표제가 시작됩니다. 그러므로 창조의 일곱 날이라는 첫 문학단락은 창세기 1장 마지막 절이 아니라 2장 3절에서 닫힙니다."]}],"lexicalCards":[{"lemma":"ברא","form":"בָּרָא","transliteration":"bārāʾ","pronunciation":"바라","verse":1,"gloss":"창조하다","note":"하나님의 창조 행위를 가리키며 어휘 자체로 무로부터의 창조를 정의하지 않습니다."},{"lemma":"רוח אלהים","form":"רוּחַ אֱלֹהִים","transliteration":"rûaḥ ʾĕlōhîm","pronunciation":"루아흐 엘로힘","verse":2,"gloss":"하나님의 영/바람","note":"복수의 번역 견해를 보존합니다."},{"lemma":"צלם","form":"צֶלֶם","transliteration":"ṣelem","pronunciation":"첼렘","verse":26,"gloss":"형상","note":"남자와 여자에게 함께 주어지는 하나님의 형상과 사명."},{"lemma":"שבת","form":"שָׁבַת","transliteration":"šāḇat","pronunciation":"샤바트","verse":2,"gloss":"일을 그치다/쉬다","note":"2장 2–3절의 일곱째 날, 창조 완결의 동사."}],"canonicalLinks":[{"ref":"출애굽기 20:8–11","note":"하나님의 일곱째 날 안식이 안식일 계명의 신학적 근거로 사용됩니다."},{"ref":"시편 104편","note":"창조 세계에 대한 하나님의 지속적인 돌보심을 노래합니다."},{"ref":"요한복음 1:1–3; 골로새서 1:15–17","note":"신약은 말씀·그리스도를 통한 창조를 증언합니다."},{"ref":"히브리서 4:3–11","note":"안식의 주제가 하나님의 백성이 참여할 쉼으로 발전합니다."}],"cautions":["1:1의 문장 구조, 1:2의 영/바람, 창조의 날, 1:26의 복수 화법은 해석 논의가 남아 있습니다.","2:2 일곱째/여섯째 날의 본문 전승 차이를 현대 연대 확증으로 삼지 않습니다.","본문 밖의 절대 연대, 창조 과정의 과학적 메커니즘, 신화 직접 차용을 증명했다고 주장하지 않습니다."]},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_GENESIS_01_05_WORBS_20261008_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/창세기/JBC_GENESIS_01_05_WORBS_20261008_01.md","sourceSha256":"022957cbf8d1334a5e30cad4f928b6f5a8fbde2bed4e494c51bc5a10ee943624","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"QUALITY_PASS_WITH_VERIFY_STAGE_HOLD","qualityStatus":"PASS_WITH_VERIFY","sourceDocumentEmbeddedStatus":"CANDIDATE_PENDING_INDEPENDENT_QA","statusBasis":"CAPTAIN_EXPLICIT_PROJECTION_TASK_20261008","externalRelease":"NOT_AUTHORIZED","registryPointerChange":"PROHIBITED","canonicalEntityPromotion":"PROHIBITED","passage":{"book":"gen","chapter":1,"v1":1,"v2":31,"ref":"창세기 1장"},"title":"말씀으로 세워진 선한 창조 질서","overview":["창세기 1장은 하나님이 말씀하시고, 이루어지고, 구분·명명·평가하시는 반복 구조를 통해 혼돈하고 비어 있는 상태를 질서 있는 생명의 세계로 세우시는 장면을 보여 줍니다.","1–3일과 4–6일의 영역 형성/채움 병행은 유익한 문학적 관찰이지만 모든 요소를 기계적으로 일대일 대응시키는 틀은 아닙니다. 창조 단락의 완결은 장 경계를 넘어 2:1–3의 일곱째 날까지 이어집니다.","사람은 남자와 여자 모두 하나님의 형상으로 창조되어 복을 받고 피조 세계를 책임 있게 다스리는 사명을 받습니다."],"centralMessage":"하나님은 말씀으로 선한 창조 질서를 세우시고 남자와 여자 모두를 자신의 형상으로 세워 피조 세계를 책임 있게 돌보도록 하십니다.","sections":[{"id":"gen1-1-5","v1":1,"v2":5,"title":"창조의 시작과 빛","paragraphs":["1:1–2는 하나님과 아직 정돈되지 않은 땅의 상태를 제시하고 3절부터 하나님의 말씀이 질서를 세우기 시작합니다.","1:1의 문법은 독립절/종속절 논의가 있으며, בָּרָא 자체가 사전적으로 ‘무에서’를 뜻한다고 단정하지 않습니다."]},{"id":"gen1-6-13","v1":6,"v2":13,"title":"공간의 구분과 생명의 터전","paragraphs":["궁창, 바다와 뭍, 식물이 차례로 구분되고 이름 붙여지며 생명이 거할 질서가 형성됩니다.","תֹהוּ וָבֹהוּ는 아직 정돈되지 않고 비어 있는 상태를 나타내며 악한 물질이라는 뜻을 자동 포함하지 않습니다."]},{"id":"gen1-14-23","v1":14,"v2":23,"title":"광명체와 생물","paragraphs":["광명체는 계절과 날과 해를 표시하고 땅을 비추는 기능을 받습니다. 해와 달의 신격화를 중심에 두지 않는 서술과 잘 맞습니다.","물과 하늘의 생물에게 생육하고 번성하라는 복이 주어집니다."]},{"id":"gen1-24-31","v1":24,"v2":31,"title":"사람과 심히 좋은 창조","paragraphs":["사람은 하나님의 형상과 모양으로 남자와 여자 모두 창조되어 다스림의 책임을 받습니다.","마지막 평가는 ‘심히 좋았더라’이며 창조주의 선한 평가가 장 전체의 절정을 이룹니다."]},{"id":"gen1-depth-delta","v1":1,"v2":31,"title":"창조 이야기를 깊이 읽기","paragraphs":["창세기 1장 1절의 첫 표현은 ‘태초에 하나님이 천지를 창조하셨다’라는 완결된 선언으로 읽을 수도 있고, ‘하나님이 천지를 창조하기 시작하실 때’라는 시간 표현으로 이해할 수도 있습니다. 두 번역은 이어지는 2–3절을 연결하는 방식에 차이가 있습니다. 그러나 어느 쪽이든 창조 이야기는 하나님의 말씀으로 세상이 질서를 갖추어 가는 모습을 보여 줍니다.","1장 2절의 ‘하나님의 영’이라는 표현은 ‘하나님의 바람’으로 번역하기도 합니다. 두 번역은 창조의 시작을 설명하는 방식에 차이를 주지만, 한 단어만으로 성령에 관한 모든 교리를 설명할 수는 없습니다. 이어서 하나님은 남자와 여자를 모두 자신의 형상으로 창조하시고 세상을 돌볼 책임을 맡기십니다. 하나님의 형상은 인간의 존엄뿐 아니라 맡겨진 사명과도 연결됩니다."]}],"lexicalCards":[{"lemma":"ברא","form":"בָּרָא","transliteration":"bārāʾ","pronunciation":"바라","verse":1,"gloss":"창조하다","morphology":"Qal 완료 3인칭 남성 단수","note":"하나님의 창조 행위를 가리키지만 동사 하나만으로 creatio ex nihilo 전체 교리를 증명하지 않습니다."},{"lemma":"רוח אלהים","form":"רוּחַ אֱלֹהִים","transliteration":"rûaḥ ʾĕlōhîm","pronunciation":"루아흐 엘로힘","verse":2,"gloss":"하나님의 영/바람","morphology":"명사 연쇄","note":"번역 논의가 남아 있으며 문맥과 정경을 함께 보아야 합니다."},{"lemma":"צלם","form":"צֶלֶם","transliteration":"ṣelem","pronunciation":"첼렘","verse":26,"gloss":"형상","morphology":"명사","note":"דְּמוּת와 함께 인간의 하나님을 닮은 지위와 사명을 설명합니다."},{"lemma":"טוב","form":"טוֹב","transliteration":"ṭôḇ","pronunciation":"토브","verse":31,"gloss":"좋음","morphology":"형용사","note":"창조주의 평가이며 1:31의 ‘심히 좋음’이 절정입니다."}],"cautions":["창세기 1장의 창조 단락은 2:1–3에서 완결되므로 현대 장 구분만으로 문학적 경계를 자르지 않습니다.","בָּרָא의 어원이나 사전 뜻만으로 ‘무에서의 창조’를 확정하지 않습니다.","1:26의 ‘우리’를 문법 하나만으로 삼위일체의 직접 증명으로 만들지 않습니다.","창조의 ‘날’ 해석과 1:1 문법은 경쟁 견해를 남겨 둡니다."],"canonicalLinks":[{"ref":"창세기 2:1–3","note":"일곱째 날의 안식이 창조 단락을 완결합니다."},{"ref":"시편 104편","note":"창조 질서와 하나님의 지속적 돌보심을 찬양합니다."},{"ref":"요한복음 1:1–3; 골로새서 1:15–17","note":"신약은 그리스도를 통한 창조를 증언합니다."},{"ref":"출애굽기 20:8–11","note":"창조의 안식이 이스라엘의 노동과 쉼의 질서에 연결됩니다."}],"depthDeltaId":"JBC_GENESIS_01_05_WORBS_DEPTH_DELTA_20261008_01","depthDeltaSha256":"0dad5dc1696842e9a77433589f57f05262e1e7c2c66f48b0d85817c28cc1437c"},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_GENESIS_01_05_WORBS_20261008_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/창세기/JBC_GENESIS_01_05_WORBS_20261008_01.md","sourceSha256":"022957cbf8d1334a5e30cad4f928b6f5a8fbde2bed4e494c51bc5a10ee943624","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"QUALITY_PASS_WITH_VERIFY_STAGE_HOLD","qualityStatus":"PASS_WITH_VERIFY","sourceDocumentEmbeddedStatus":"CANDIDATE_PENDING_INDEPENDENT_QA","statusBasis":"CAPTAIN_EXPLICIT_PROJECTION_TASK_20261008","externalRelease":"NOT_AUTHORIZED","registryPointerChange":"PROHIBITED","canonicalEntityPromotion":"PROHIBITED","passage":{"book":"gen","chapter":2,"v1":1,"v2":25,"ref":"창세기 2장"},"title":"생명, 경계, 동역 관계의 형성","overview":["2:1–3은 창조의 결말이며 2:4부터 초점이 인간과 동산, 명령과 관계로 좁혀집니다.","사람은 흙으로 지음 받고 생기를 받아 살아 있는 존재가 되며, 동산을 경작하고 지키는 사명과 함께 선악을 알게 하는 나무에 대한 경계를 받습니다.","‘그에게 상응하는 돕는 이’의 창조와 한 몸의 결합은 인간이 홀로 존재하도록 지어지지 않았음을 보여 줍니다."],"centralMessage":"하나님은 사람에게 생명과 사명과 경계를 주시고, 서로 상응하는 관계 속에서 함께 살아가도록 인간 공동체를 세우십니다.","sections":[{"id":"gen2-1-3","v1":1,"v2":3,"title":"일곱째 날의 안식","paragraphs":["하나님은 창조를 마치고 일곱째 날을 복 주고 거룩하게 하십니다.","이 단락은 창세기 1장의 창조 서사를 완결합니다."]},{"id":"gen2-4-14","v1":4,"v2":14,"title":"사람과 에덴 동산","paragraphs":["2:4의 톨레도트 표제가 새로운 초점을 열고, 하나님은 흙으로 사람을 지으시고 생기를 불어넣으십니다.","에덴과 네 강은 명명되지만 에덴 자체의 정확한 현대 좌표를 확정할 수 없습니다."]},{"id":"gen2-15-17","v1":15,"v2":17,"title":"돌봄의 사명과 명령의 경계","paragraphs":["사람은 동산을 ‘경작하고 지키도록’ 두어지고 선악을 알게 하는 나무에 대한 명령을 받습니다.","생명은 무제한 자율이 아니라 하나님과의 신뢰 관계 안에서 주어집니다."]},{"id":"gen2-18-25","v1":18,"v2":25,"title":"상응하는 돕는 이와 한 몸","paragraphs":["혼자 있는 것이 좋지 않다는 선언 뒤에 여자가 지어지고 서로를 알아보는 관계가 형성됩니다.","עֵזֶר כְּנֶגְדּוֹ는 열등한 보조자라는 뜻을 자동 포함하지 않으며 2:24는 깊은 결합을 표현합니다."]},{"id":"gen2-depth-delta","v1":1,"v2":25,"title":"생명과 동산의 의미 살펴보기","paragraphs":["창세기 2장 1–3절은 일곱째 날의 안식으로 앞선 창조 이야기를 마무리합니다. 4절부터는 사람이 어떻게 지음받고 어떤 관계와 책임을 받았는지에 초점이 맞추어집니다. 4절의 히브리어 표현은 이렇게 새로운 이야기가 시작됨을 알려 주는 표제로 이해할 수 있습니다.","하나님이 사람에게 동산을 ‘경작하고 지키라’고 하신 말씀은 주어진 세계를 돌보고 보전할 책임을 보여 줍니다. 이 표현을 훗날 성전에서 섬기는 일과 연결해 읽는 견해도 있지만, 여기서 아담을 제사장으로 임명했다고 직접 말하는 것은 아닙니다. 또한 금지된 열매를 먹으면 죽으리라는 경고와 실제로 열매를 먹은 뒤에도 사람이 살아 있는 이야기를 함께 살펴야 합니다. 죽음이 어떤 방식으로 시작되었는지는 본문을 신중히 읽어야 하는 부분입니다."]}],"lexicalCards":[{"lemma":"אדם / אדמה","form":"אָדָם / אֲדָמָה","transliteration":"ʾādām / ʾădāmāh","pronunciation":"아담 / 아다마","verse":7,"gloss":"사람 / 땅","morphology":"명사","note":"소리 관계가 인간의 피조성과 땅에 대한 소명을 부각합니다."},{"lemma":"נפש חיה","form":"נֶפֶשׁ חַיָּה","transliteration":"nep̄eš ḥayyāh","pronunciation":"네페쉬 하야","verse":7,"gloss":"살아 있는 존재","morphology":"명사+형용사","note":"‘불멸의 영혼’만을 뜻하는 기술어로 좁히지 않습니다."},{"lemma":"עבד / שמר","form":"עָבַד / שָׁמַר","transliteration":"ʿāḇad / šāmar","pronunciation":"아바드 / 샤마르","verse":15,"gloss":"일하다·섬기다 / 지키다","morphology":"동사","note":"동산을 돌보고 보전하는 사명을 함께 표현합니다."},{"lemma":"עזר כנגדו","form":"עֵזֶר כְּנֶגְדּוֹ","transliteration":"ʿēzer kənegdô","pronunciation":"에제르 케네그도","verse":18,"gloss":"그에게 상응하는 돕는 이","morphology":"명사구","note":"열등한 보조자를 뜻한다고 자동 해석하지 않습니다."},{"lemma":"דבק","form":"דָּבַק","transliteration":"dāḇaq","pronunciation":"다바크","verse":24,"gloss":"붙다·연합하다","morphology":"Qal 동사","note":"부부 결합의 강도와 지속성을 표현합니다."}],"cautions":["티그리스와 유프라테스의 식별 가능성과 에덴 동산의 정확한 위치 확정은 별개의 문제입니다.","비손·기혼·하윌라·구스의 동일시는 논쟁적이므로 좌표나 현대 지명을 생성하지 않습니다.","2:24에 ‘언약’이라는 명사가 직접 나오지 않습니다.","창세기 1장과 2장을 단순한 중복 또는 모순으로 미리 판정하지 않습니다."],"canonicalLinks":[{"ref":"창세기 1장","note":"인간 창조의 보편적 관점과 2장의 관계·사명 중심 관점을 함께 읽습니다."},{"ref":"창세기 3장","note":"2장에서 주어진 신뢰·경계·관계가 어떻게 무너지는지 이어집니다."},{"ref":"마가복음 10:6–9","note":"예수께서 창 1:27과 2:24를 결합하여 혼인의 연합을 논증합니다."},{"ref":"요한계시록 22:1–2","note":"에덴의 생명 이미지가 새 창조에서 변주됩니다."}],"depthDeltaId":"JBC_GENESIS_01_05_WORBS_DEPTH_DELTA_20261008_01","depthDeltaSha256":"0dad5dc1696842e9a77433589f57f05262e1e7c2c66f48b0d85817c28cc1437c"},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_GENESIS_01_05_WORBS_20261008_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/창세기/JBC_GENESIS_01_05_WORBS_20261008_01.md","sourceSha256":"022957cbf8d1334a5e30cad4f928b6f5a8fbde2bed4e494c51bc5a10ee943624","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"QUALITY_PASS_WITH_VERIFY_STAGE_HOLD","qualityStatus":"PASS_WITH_VERIFY","sourceDocumentEmbeddedStatus":"CANDIDATE_PENDING_INDEPENDENT_QA","statusBasis":"CAPTAIN_EXPLICIT_PROJECTION_TASK_20261008","externalRelease":"NOT_AUTHORIZED","registryPointerChange":"PROHIBITED","canonicalEntityPromotion":"PROHIBITED","passage":{"book":"gen","chapter":3,"v1":1,"v2":24,"ref":"창세기 3장"},"title":"신뢰의 붕괴와 심판 가운데 남은 생명","overview":["뱀의 질문은 하나님의 말씀과 선하심에 대한 신뢰를 흔들고, 인간은 금지된 열매를 취한 뒤 수치와 숨음, 책임 전가를 경험합니다.","하나님의 심문과 선고는 뱀·여자·남자와 땅에 대한 결과를 드러내며 죽음의 현실이 인간 삶 안으로 들어옵니다.","그럼에도 하나님은 인간에게 말을 거시고 옷을 입히시며, 생명나무 접근을 차단한 채 동산 밖으로 내보내십니다."],"centralMessage":"하나님을 신뢰하지 않고 스스로 선악의 기준을 잡으려 한 인간의 불순종은 수치와 관계 붕괴와 죽음을 가져오지만, 심판 가운데서도 하나님은 인간을 버리지 않고 생명의 역사를 이어 가십니다.","sections":[{"id":"gen3-1-7","v1":1,"v2":7,"title":"유혹과 불순종","paragraphs":["뱀은 하나님의 명령을 비틀어 질문하고 여자는 열매를 보고 취하며 남자도 먹습니다.","2:25의 벌거벗음과 3:7의 수치가 대비되어 신뢰 붕괴의 결과를 보여 줍니다."]},{"id":"gen3-8-13","v1":8,"v2":13,"title":"숨음과 책임 전가","paragraphs":["하나님이 인간을 찾고 질문하시지만 남자와 여자는 책임을 다른 존재에게 돌립니다.","본문은 죄 이후 하나님과 인간, 인간과 인간 사이의 관계 단절을 서사적으로 보여 줍니다."]},{"id":"gen3-14-21","v1":14,"v2":21,"title":"선고와 옷 입힘","paragraphs":["뱀·여자·남자에게 각각 결과가 선고되고 땅도 저주 아래 놓입니다.","3:21의 가죽옷은 하나님이 수치를 가리는 실제 행위이지만 본문 자체가 희생 제사나 속죄 피를 명시하지 않습니다."]},{"id":"gen3-22-24","v1":22,"v2":24,"title":"동산 밖으로의 추방","paragraphs":["생명나무 접근이 차단되고 인간은 에덴 동산에서 내보내집니다.","추방은 실제 이동 사건이지만 본문에는 정확한 출발·도착 좌표나 route geometry가 없습니다."]},{"id":"gen3-depth-delta","v1":1,"v2":24,"title":"불순종과 하나님의 돌보심 이해하기","paragraphs":["하나님은 뱀과 여자의 후손 사이에 적대가 있을 것이라고 말씀하십니다. 여기서 ‘후손’이라는 말은 한 사람만이 아니라 이어지는 자손들을 가리킬 수도 있습니다. 그리스도인들은 성경 전체의 흐름 속에서 이 말씀을 예수 그리스도의 승리와 연결해 읽어 왔습니다. 다만 창세기 3장 15절 자체가 예수님의 생애를 구체적으로 설명하고 있는 것은 아닙니다.","하나님은 두려움과 수치 가운데 있는 아담과 하와에게 가죽옷을 지어 입히십니다. 이 장면은 불순종 이후에도 하나님이 인간을 돌보신다는 사실을 보여 줍니다. 이를 희생이나 속죄와 연결해 묵상할 수는 있지만, 본문은 동물을 잡아 제사를 드리거나 피로 죄를 속했다는 과정을 직접 말하지는 않습니다."]}],"lexicalCards":[{"lemma":"ערום","form":"עָרוּם","transliteration":"ʿārûm","pronunciation":"아룸","verse":1,"gloss":"간교한","morphology":"형용사","note":"2:25의 ‘벌거벗은’과 유사 음형으로 문학적 아이러니를 만듭니다."},{"lemma":"נחש","form":"נָחָשׁ","transliteration":"nāḥāš","pronunciation":"나하쉬","verse":1,"gloss":"뱀","morphology":"명사","note":"창세기 3장 자체는 이 존재를 ‘사탄’이라고 명명하지 않습니다."},{"lemma":"זרע","form":"זֶרַע","transliteration":"zeraʿ","pronunciation":"제라","verse":15,"gloss":"씨·자손","morphology":"명사","note":"집합적 후손 의미와 후대 정경에서 한 개인에게 집중되는 읽기를 구분합니다."},{"lemma":"ארר","form":"אָרוּר","transliteration":"ʾārûr","pronunciation":"아루르","verse":17,"gloss":"저주받은","morphology":"수동분사","note":"뱀과 땅에 사용되며 사람에게 동일 형식의 직접 저주 선언이 주어진 것과 구별합니다."}],"cautions":["3:15의 본문 직접 의미와 그리스도 승리로 읽는 후대 정경적 해석을 구분합니다.","3:21의 가죽옷에서 동물 희생·피 흘림·속죄 제의를 직접 확정하지 않습니다.","창세기 3장의 뱀을 canonical person identity로 자동 ‘사탄’과 병합하지 않습니다.","에덴 동쪽이라는 방향 표현만으로 정확한 지리 경로나 좌표를 생성하지 않습니다."],"canonicalLinks":[{"ref":"창세기 2:16–17","note":"금지 명령과 죽음 경고가 3장의 불순종과 직접 연결됩니다."},{"ref":"로마서 5:12–21","note":"바울은 아담과 그리스도를 대조하여 죄·죽음과 은혜·생명의 대표성을 발전시킵니다."},{"ref":"고린도후서 11:3","note":"뱀의 미혹을 공동체의 신실함에 대한 경고로 사용합니다."},{"ref":"요한계시록 12:9; 20:2; 22장","note":"정경 후반은 옛 뱀과 사탄을 연결하고 생명나무 접근의 회복을 보여 줍니다."}],"depthDeltaId":"JBC_GENESIS_01_05_WORBS_DEPTH_DELTA_20261008_01","depthDeltaSha256":"0dad5dc1696842e9a77433589f57f05262e1e7c2c66f48b0d85817c28cc1437c"},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_GENESIS_01_05_WORBS_20261008_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/창세기/JBC_GENESIS_01_05_WORBS_20261008_01.md","sourceSha256":"022957cbf8d1334a5e30cad4f928b6f5a8fbde2bed4e494c51bc5a10ee943624","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"QUALITY_PASS_WITH_VERIFY_STAGE_HOLD","qualityStatus":"PASS_WITH_VERIFY","sourceDocumentEmbeddedStatus":"CANDIDATE_PENDING_INDEPENDENT_QA","statusBasis":"CAPTAIN_EXPLICIT_PROJECTION_TASK_20261008","externalRelease":"NOT_AUTHORIZED","registryPointerChange":"PROHIBITED","canonicalEntityPromotion":"PROHIBITED","passage":{"book":"gen","chapter":4,"v1":1,"v2":26,"ref":"창세기 4장"},"title":"죄의 문 앞에서 형제의 피와 보존의 표까지","overview":["가인과 아벨은 서로 다른 예물을 하나님께 드리지만 본문은 재료의 차이만으로 열납 여부를 설명하지 않습니다.","가인은 하나님의 경고에도 아벨을 죽이고, 피의 호소와 심문, 형벌을 경험합니다. 그러나 하나님은 그에게 보호의 표도 주십니다.","가인의 후손에게 문화 활동과 폭력의 확대가 함께 나타나고, 마지막에는 셋과 에노스 계보에서 여호와의 이름을 부르는 장면이 이어집니다."],"centralMessage":"죄는 경고받고 다스려야 할 힘이지만 인간은 형제를 해치는 폭력으로 그것을 확장합니다. 하나님은 살인의 악을 심판하시면서도 무제한 보복을 허용하지 않고 생명의 역사를 보존하십니다.","sections":[{"id":"gen4-1-7","v1":1,"v2":7,"title":"가인과 아벨의 예물","paragraphs":["가인과 아벨은 각각 땅의 소산과 양의 첫 새끼를 예물로 드립니다.","מִנְחָה는 두 예물을 모두 가리키므로 ‘피 없는 제물이라 거절되었다’고 단정하지 않습니다."]},{"id":"gen4-8-16","v1":8,"v2":16,"title":"살인, 심문, 형벌과 보호","paragraphs":["가인은 아벨을 죽이고 ‘내가 내 아우를 지키는 자니이까’라고 답합니다. 아벨의 피는 땅에서 하나님께 호소합니다.","하나님은 가인을 벌하시지만 표를 주어 무제한 보복을 막으십니다. 표의 물리적 형태는 알려 주지 않습니다."]},{"id":"gen4-17-24","v1":17,"v2":24,"title":"가인의 계보와 문화·폭력의 확대","paragraphs":["성읍, 목축, 음악, 금속 제작과 관련된 인물들이 소개되지만 이것이 모든 기술의 절대 최초 연대를 제공하지 않습니다.","라멕의 노래는 보복 폭력의 확대를 드러냅니다."]},{"id":"gen4-25-26","v1":25,"v2":26,"title":"셋과 에노스","paragraphs":["아담과 하와에게 셋이 주어지고 에노스 시대에 여호와의 이름을 부르는 장면이 나타납니다.","이 표현을 곧바로 최초의 조직 종교 기관의 설립으로 확대하지 않습니다."]},{"id":"gen4-depth-delta","v1":1,"v2":26,"title":"가인과 아벨의 이야기 살펴보기","paragraphs":["하나님은 분노한 가인에게 죄가 문 앞에 엎드려 그를 노리고 있다고 경고하십니다. 이 구절의 히브리어 표현은 문법과 번역이 쉽지 않아 ‘죄’와 ‘속죄제’를 둘러싼 해석도 논의됩니다. 그러나 이야기의 흐름에서 분명한 것은 가인이 분노와 죄의 유혹에 끌려가지 말고 그것을 다스려야 한다는 경고를 받았다는 사실입니다.","가인은 땅의 소산을, 아벨은 양의 첫 새끼를 하나님께 드렸습니다. 성경은 두 사람이 드린 것을 모두 ‘예물’이라고 부릅니다. 그러므로 가인의 예물이 곡식이었기 때문에 거절되었다고 단정할 수 없습니다. 히브리서 11장 4절은 아벨의 믿음을 강조하지만, 창세기 본문은 가인의 속마음을 모두 설명하지 않습니다."]}],"lexicalCards":[{"lemma":"מנחה","form":"מִנְחָה","transliteration":"minḥāh","pronunciation":"민하","verse":3,"gloss":"예물·봉헌물","morphology":"명사","note":"곡식과 가축에서 드린 예물 모두에 사용됩니다."},{"lemma":"חטאת","form":"חַטָּאת","transliteration":"ḥaṭṭāʾt","pronunciation":"하타트","verse":7,"gloss":"죄","morphology":"명사","note":"문에 엎드린 죄의 위협을 의인화합니다. 문법과 ‘죄/속죄제’ 논의는 남아 있습니다."},{"lemma":"אות","form":"אוֹת","transliteration":"ʾôt","pronunciation":"오트","verse":15,"gloss":"표·징표","morphology":"명사","note":"가인을 보호하는 표이지만 그 물리적 형태는 본문이 말하지 않습니다."},{"lemma":"קרא בשם יהוה","form":"קָרָא בְּשֵׁם יְהוָה","transliteration":"qārāʾ bəšēm YHWH","pronunciation":"카라 베쉠 아도나이","verse":26,"gloss":"여호와의 이름을 부르다","morphology":"동사구","note":"예배적 호소와 연결되지만 제도화된 종교 기관을 직접 증명하지 않습니다."}],"cautions":["예물의 재료만으로 가인의 제사가 거절된 원인을 확정하지 않습니다.","가인의 내적 동기를 ‘형식적 예배’ 하나로 전부 설명하지 않습니다.","‘놋 땅’은 에덴 동편이라는 상대적 위치만 주어지므로 현대 좌표를 발급하지 않습니다.","4:17의 에녹과 5:21–24의 에녹을 동일 인물로 병합하지 않습니다."],"canonicalLinks":[{"ref":"창세기 3장","note":"무너진 신뢰가 형제 살해라는 사회적 폭력으로 확대됩니다."},{"ref":"히브리서 11:4","note":"아벨의 제사를 믿음과 연결합니다."},{"ref":"히브리서 12:24","note":"아벨의 피와 예수의 피를 대비합니다."},{"ref":"요한일서 3:12","note":"가인의 악한 행위를 형제 사랑의 반례로 사용합니다."}],"depthDeltaId":"JBC_GENESIS_01_05_WORBS_DEPTH_DELTA_20261008_01","depthDeltaSha256":"0dad5dc1696842e9a77433589f57f05262e1e7c2c66f48b0d85817c28cc1437c"},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"JBC_GENESIS_01_05_WORBS_20261008_01","sourcePath":"G:/내 드라이브/Projects/옵시디언/Jude_Research/02_연구물/창세기/JBC_GENESIS_01_05_WORBS_20261008_01.md","sourceSha256":"022957cbf8d1334a5e30cad4f928b6f5a8fbde2bed4e494c51bc5a10ee943624","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"QUALITY_PASS_WITH_VERIFY_STAGE_HOLD","qualityStatus":"PASS_WITH_VERIFY","sourceDocumentEmbeddedStatus":"CANDIDATE_PENDING_INDEPENDENT_QA","statusBasis":"CAPTAIN_EXPLICIT_PROJECTION_TASK_20261008","externalRelease":"NOT_AUTHORIZED","registryPointerChange":"PROHIBITED","canonicalEntityPromotion":"PROHIBITED","passage":{"book":"gen","chapter":5,"v1":1,"v2":32,"ref":"창세기 5장"},"title":"‘죽었더라’의 반복 속에 놓인 동행과 다음 세대","overview":["창세기 5장은 하나님의 형상과 남녀의 복을 다시 불러오며 아담에서 노아까지 이어지는 선형 족보를 제시합니다.","‘낳고 … 살고 … 죽었더라’라는 반복은 생명의 계승과 죽음의 보편성을 함께 드러내고, 에녹의 ‘하나님과 동행’은 그 반복 속의 중요한 예외로 강조됩니다.","노아의 출생과 이름 풀이는 땅의 수고와 저주를 되돌아보면서 6–9장의 홍수 이야기를 준비합니다."],"centralMessage":"죽음이 세대를 지배하는 현실 속에서도 하나님의 형상과 약속의 계보는 이어지고, 에녹의 동행은 하나님과의 관계가 죽음보다 크다는 정경적 소망을 열어 둡니다.","sections":[{"id":"gen5-1-20","v1":1,"v2":20,"title":"아담에서 야렛까지","paragraphs":["5:1의 ‘아담의 계보의 책’은 새 계보 단락의 표제입니다.","각 세대의 출생과 수명, 죽음이 반복되며 생명의 계승과 죽음의 보편성이 함께 드러납니다."]},{"id":"gen5-21-24","v1":21,"v2":24,"title":"하나님과 동행한 에녹","paragraphs":["에녹에게는 반복되는 ‘죽었더라’ 대신 하나님과 동행했고 하나님이 데려가셨다는 독특한 결말이 주어집니다.","히브리서 11:5는 이를 ‘죽음을 보지 않았다’고 명시적으로 해석합니다."]},{"id":"gen5-25-32","v1":25,"v2":32,"title":"므두셀라에서 노아까지","paragraphs":["라멕은 노아의 이름을 땅의 수고와 위로에 연결하며 홍수 서사를 준비합니다.","노아의 세 아들 셈·함·야벳은 이후 민족 서사의 계보적 출발점이 됩니다."]},{"id":"gen5-depth-delta","v1":1,"v2":32,"title":"족보와 에녹의 동행 이해하기","paragraphs":["창세기 5장은 여러 세대가 태어나고 살다가 죽는 모습을 반복해서 기록합니다. 그런데 에녹에 대해서는 특별히 ‘하나님과 동행하였다’고 말하며, 하나님이 그를 데려가셨다고 기록합니다. 훗날 히브리서 11장 5절은 에녹이 죽음을 보지 않았다고 설명합니다. 두 본문을 함께 읽되, 창세기 자체가 어디까지 말하는지도 구분하는 것이 좋습니다.","창세기 5장에 기록된 조상들의 나이는 전해 내려온 성경 본문 전통에 따라 일부 숫자가 다릅니다. 오늘날 일반적으로 사용하는 히브리어 본문과 고대 그리스어 번역본, 사마리아 오경 사이에 차이가 있기 때문입니다. 따라서 이 족보의 나이를 단순히 더해서 세상이 창조된 정확한 연도를 확정하는 것은 신중해야 합니다."]}],"lexicalCards":[{"lemma":"ספר תולדת אדם","form":"סֵפֶר תּוֹלְדֹת אָדָם","transliteration":"sēp̄er tôlədōṯ ʾādām","pronunciation":"세페르 톨레도트 아담","verse":1,"gloss":"아담의 계보의 책","morphology":"명사 연쇄","note":"새 계보 단락의 표제입니다."},{"lemma":"מות","form":"וַיָּמֹת","transliteration":"wayyāmōṯ","pronunciation":"와야모트","verse":5,"gloss":"그리고 그가 죽었다","morphology":"Qal wayyiqtol 3인칭 남성 단수","note":"계보에서 반복되는 죽음의 후렴을 이룹니다."},{"lemma":"הלך","form":"וַיִּתְהַלֵּךְ","transliteration":"wayyithallēḵ","pronunciation":"와이트할레크","verse":22,"gloss":"동행하였다","morphology":"Hitpael wayyiqtol 3인칭 남성 단수","note":"에녹의 삶을 특징짓는 핵심 동사입니다."},{"lemma":"לקח","form":"לָקַח","transliteration":"lāqaḥ","pronunciation":"라카흐","verse":24,"gloss":"취하다·데려가다","morphology":"Qal 완료","note":"에녹의 독특한 결말을 표시하지만 창 5장 자체가 ‘부활/승천’이라는 용어를 사용하지 않습니다."}],"cautions":["MT·사마리아 오경·LXX의 족보 연령 수치가 다르므로 창 5장만으로 현대 절대 연대를 확정하지 않습니다.","숫자 대조 전체의 독립 원문 검증은 VERIFY 상태로 남깁니다.","에녹의 ‘부활/승천’을 창 5장 본문의 직접 진술로 확정하지 않습니다.","창 4장과 5장의 유사 인물명을 기계적으로 동일인으로 병합하지 않습니다."],"canonicalLinks":[{"ref":"창세기 1:26–28","note":"하나님의 형상과 남녀의 복이 5:1–2에서 다시 불려 옵니다."},{"ref":"창세기 3:17–19","note":"땅의 수고와 죽음의 현실이 족보의 반복과 노아의 이름 풀이 배경이 됩니다."},{"ref":"히브리서 11:5–6","note":"에녹의 동행을 믿음과 죽음을 보지 않음으로 해석합니다."},{"ref":"누가복음 3:36–38","note":"아담에 이르는 계보를 예수의 계보와 연결합니다."}],"depthDeltaId":"JBC_GENESIS_01_05_WORBS_DEPTH_DELTA_20261008_01","depthDeltaSha256":"0dad5dc1696842e9a77433589f57f05262e1e7c2c66f48b0d85817c28cc1437c"},{"researchId":"JBC_GENESIS_06_08_WORBS_20261009_01","sourceSha256":"1883356ab6a2fe9dd5c334dc5479c08c2ef14ceafb0ec62952eb58f5890c8ff3","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"REVIEW_ONLY","externalRelease":"NOT_AUTHORIZED","title":"창세기 6장 — 무너진 세계 속에서 시작되는 보존","passage":{"book":"gen","chapter":6,"v1":1,"v2":22,"ref":"창세기 6장"},"overview":["창세기 6장은 인류의 번성이라는 창조의 복이 폭력과 타락으로 왜곡된 현실을 드러냅니다. 하나님은 인간의 악을 보시고 마음 아파하시며 심판을 선언하지만, 노아를 향한 은혜와 언약의 말씀을 통해 생명을 보존할 길도 여십니다. 중심은 거대한 배의 제작 기술보다 죄로 가득한 땅을 향한 하나님의 도덕적 판단과 보존의 약속입니다."],"centralMessage":"창세기 6장은 인류의 번성이라는 창조의 복이 폭력과 타락으로 왜곡된 현실을 드러냅니다. 하나님은 인간의 악을 보시고 마음 아파하시며 심판을 선언하지만, 노아를 향한 은혜와 언약의 말씀을 통해 생명을 보존할 길도 여십니다. 중심은 거대한 배의 제작 기술보다 죄로 가득한 땅을 향한 하나님의 도덕적 판단과 보존의 약속입니다.","sections":[{"id":"gen6-1-4","v1":1,"v2":4,"title":"번성의 시대에 드러난 왜곡된 취함","paragraphs":["앞선 5장은 아담의 계보를 따라 생명의 연속성과 죽음의 반복을 보여 줍니다. 6장은 사람이 땅에 많아지고 딸들이 태어나는 장면으로 시작합니다. 번성은 창조 때 받은 복과 연결되지만, 그 복이 올바른 관계를 자동으로 보장하지는 않습니다. '하나님의 아들들'은 여자들의 아름다움을 보고 자기들이 택한 여자들을 아내로 취합니다. '보고–좋다고 판단하고–취하는' 움직임은 3:6의 취함을 떠올리게 하지만, 두 사건을 완전히 같게 볼 수는 없습니다. 이 서두는 선택하는 자의 욕망과 힘이 제한 없이 행사되는 현실을 암시합니다.","'하나님의 아들들'(בְּנֵי־הָאֱלֹהִים, 브네 하엘로힘)의 정체는 논쟁적입니다. 욥기 1:6, 38:7을 근거로 하늘 존재를 보는 견해, 셋 계열의 후손으로 보는 견해, 고대 권력자나 왕족으로 보는 견해가 있습니다. 어느 하나를 본문이 명시한 사실처럼 확정할 수 없습니다. 네피림과 '용사', '이름 있는 사람들'도 단순히 현대적 의미의 거인이나 하나의 혈통으로 환원하기 어렵습니다. 이 난해한 도입은 뒤따르는 인간 세계의 도덕적 파탄을 준비합니다.","3절의 '그의 날은 백이십 년'은 인간 수명의 상한이라는 해석과 심판 전 유예 기간이라는 해석이 경쟁합니다. 이후 120세를 넘는 인물들이 등장하므로 절대 수명 제한으로 단정하기 어렵습니다. '나의 영이 영원히 사람과 함께하지 않으리라'의 히브리어 יָדוֹן(야돈)도 뜻이 확정적이지 않습니다. 분명한 것은 인간이 생명과 시간을 무제한으로 소유하지 않는다는 선언입니다."]},{"id":"gen6-5-8","v1":5,"v2":8,"title":"하나님이 보신 악과 마음의 고통","paragraphs":["5절은 인간의 악이 크고 마음의 생각이 지속적으로 악을 향한다고 서술합니다. '마음의 생각의 모든 계획'(יֵצֶר מַחְשְׁבֹת לִבּוֹ, 예체르 마흐셰보트 리보)은 행동 이전의 의도까지 무너졌음을 드러냅니다. 창세기 1장에서 창조 세계를 '좋다'고 보신 하나님이 이제 땅에 퍼진 악을 보십니다. 같은 '보심'이 창조의 선함과 인간의 타락을 대조합니다.","6절의 '한탄하셨다'(וַיִּנָּחֶם, 바이인나헴)는 하나님이 정보를 몰랐다가 뒤늦게 실수를 깨달았다는 뜻이 아닙니다. '마음에 근심하셨다'는 말과 함께 창조 세계의 파괴를 향한 하나님의 깊은 슬픔과 심판 결단을 인간이 이해할 언어로 드러냅니다. 심판은 변덕이 아니라 악이 가득한 세계를 향한 도덕적 응답입니다. 고대 메소포타미아 홍수 전승과 비교해도 창세기는 인간의 강포와 부패를 심판 이유로 분명히 말합니다.","'그러나 노아는 여호와께 은혜를 입었더라'(8절)는 선언이 흐름을 바꿉니다. חֵן(헨)은 호의와 은총을 뜻하며, 9절의 노아의 의로움과 동행을 무효로 만들지 않습니다. 본문은 은혜와 노아의 삶을 경쟁시키지 않고 함께 보여 줍니다. 멸망의 범위가 넓어질수록 이 짧은 전환은 생명을 보존하려는 하나님의 뜻을 더욱 선명하게 합니다."]},{"id":"gen6-9-13","v1":9,"v2":13,"title":"노아의 내력과 땅의 강포","paragraphs":["9절의 '노아의 내력은 이러하니라'는 톨레도트(תּוֹלְדֹת, 톨레도트) 표제로 새로운 서사 단위를 엽니다. 노아는 '의로운 사람'(צַדִּיק, 차디크), '그 세대에 흠 없는 사람'(תָּמִים, 타밈)으로 소개됩니다. 이는 노아가 절대적으로 죄가 없는 존재라는 선언보다 그 시대의 부패와 구별되는 삶의 방향을 가리킵니다. '하나님과 동행하였다'는 표현은 5:24의 에녹을 떠올리게 하며, 족보 속 죽음의 반복을 넘어 하나님과의 관계가 살아 있음을 보여 줍니다.","11–13절은 '땅'을 반복하며 부패(שָׁחַת, 샤하트 계열)와 강포(חָמָס, 하마스)가 충만했다고 진술합니다. 강포는 단순히 내면의 나쁜 생각이 아니라 공동체를 파괴하는 폭력과 불의를 포함합니다. 하나님이 땅을 '멸하겠다'고 하실 때도 부패를 묘사하는 어근이 연결됩니다. 인간이 파괴한 세계에 대한 하나님의 심판이 서사의 언어 안에서 맞물립니다. 홍수는 비의 양에 관한 이야기 이전에 창조 세계를 훼손한 인간 행위의 결과를 다루는 이야기입니다."]},{"id":"gen6-14-22","v1":14,"v2":22,"title":"방주와 언약, 심판을 넘어서는 생명의 준비","paragraphs":["하나님은 노아에게 방주(תֵּבָה, 테바)를 만들라고 명하십니다. 이 단어는 뒤에 출애굽기 2:3, 5에서 아기 모세를 담아 물 위에 띄운 상자에도 사용됩니다. 두 사건은 물 가운데 생명이 보존된다는 공통점을 갖지만 세부를 일대일로 맞출 필요는 없습니다. 14절의 '고페르 나무'는 정확한 수종이 확인되지 않아 특정 현대 나무로 확정할 수 없습니다. 역청을 바르고 칸과 층을 만드는 명령은 방주가 생명을 보호할 공간으로 준비됨을 보여 줍니다.","17절에서 하나님은 물을 통한 심판을 선언하시고 바로 다음 절에서 '내 언약을 너와 세우리라'(בְּרִיתִי, 베리티, '나의 언약')고 말씀하십니다. 언약의 자세한 내용은 9장에서 전개되지만 6장은 이미 심판의 예고 속에 보존의 약속을 배치합니다. 노아의 가족과 생물의 암수, 먹을 양식에 대한 명령은 구원이 한 개인의 안전을 넘어 다음 세대와 다른 생명의 지속까지 향함을 드러냅니다. 22절은 노아가 명령대로 행하였다고 마무리합니다. 은혜를 입은 삶은 하나님의 말씀에 대한 구체적인 응답으로 나타납니다."]}],"discoveries":[{"id":"gen6-deep-0","domain":"theology","title":"더 깊은 연구","paragraphs":["6:1–4의 존재들, 3절의 백이십 년, 14절의 나무 종류는 본문이 모든 세부를 확정해 주지 않는 영역입니다. 중요한 경쟁 해석을 보존하되 장 전체의 확실한 논지는 5–13절의 악과 강포, 8절의 은혜, 18절의 언약 약속에 두어야 합니다. 홍수는 아트라하시스·길가메시 서사와 비교 가능한 모티프를 공유하지만, 창세기에서 심판의 이유는 인간의 도덕적 부패와 폭력입니다. 유사성을 곧바로 문헌 의존의 증명으로 만들지 않습니다."]},{"id":"gen6-deep-1","domain":"theology","title":"심화 설명","paragraphs":["히브리서 11:7은 노아의 행동을 믿음의 응답으로 해석합니다. 베드로전서 3:20–21은 홍수와 구원을 세례에 연결하여 후대 기독교 정경 안에서 읽지만, 창세기 6장 자체가 세례나 교회의 모든 세부를 예언하는 것은 아닙니다. 출애굽기 2장의 테바는 위험한 물에서 생명을 보존하는 모티프를 확장합니다. 연결의 중심은 하나님이 심판 속에서도 생명을 보존하시고 말씀에 응답할 길을 여셨다는 데 있습니다."]},{"id":"gen6-deep-2","domain":"theology","title":"심화 설명","paragraphs":["중심 메시지: 창조 세계를 무너뜨린 인간의 악과 강포를 하나님은 외면하지 않으시지만, 은혜를 입은 노아에게 언약과 생명 보존의 길을 여시며 심판 너머의 미래를 준비하십니다."]},{"id":"gen6-deep-3","domain":"theology","title":"심화 설명","paragraphs":["---"]}],"lexicalCards":[{"verse":2,"form":"בְּנֵי־הָאֱלֹהִים","lemma":"בְּנֵי־הָאֱלֹהִים","transliteration":"","pronunciation":"브네 하엘로힘","gloss":"하나님의 아들들","morphology":"본문 문맥에서 확인","note":"정체는 하늘 존재·셋 계열·권력자 등 견해가 나뉘므로 단정하지 않습니다."},{"verse":3,"form":"יָדוֹן","lemma":"יָדוֹן","transliteration":"","pronunciation":"야돈","gloss":"다투다/머무르다(논쟁)","morphology":"본문 문맥에서 확인","note":"동사의 의미와 120년의 해석이 논쟁적입니다."},{"verse":8,"form":"חֵן","lemma":"חֵן","transliteration":"","pronunciation":"헨","gloss":"은혜·호의","morphology":"본문 문맥에서 확인","note":"노아가 하나님의 은혜를 입었다는 관계적 표현입니다."},{"verse":11,"form":"חָמָס","lemma":"חָמָס","transliteration":"","pronunciation":"하마스","gloss":"강포·폭력","morphology":"본문 문맥에서 확인","note":"땅의 부패가 사회적 폭력으로 나타납니다."},{"verse":14,"form":"תֵּבָה","lemma":"תֵּבָה","transliteration":"","pronunciation":"테바","gloss":"방주·상자","morphology":"본문 문맥에서 확인","note":"출애굽기 2장의 모세를 담은 상자와 같은 명사입니다."},{"verse":18,"form":"בְּרִית","lemma":"בְּרִית","transliteration":"","pronunciation":"베리트","gloss":"언약","morphology":"본문 문맥에서 확인","note":"하나님이 노아와 언약을 세우실 것을 예고합니다."}],"cautions":["하나님의 아들들·네피림의 정체를 본문이 직접 확정한다고 말하지 않습니다.","6:3의 120년과 히브리어 יָדוֹן은 경쟁 해석을 보존합니다.","고페르 나무의 정확한 수종이나 방주 위치를 확정하지 않습니다."],"canonicalLinks":[{"ref":"창세기 5:24","note":"에녹과 노아의 하나님과 동행함을 연결합니다."},{"ref":"출애굽기 2:3–5","note":"동일 명사 테바가 생명 보존의 상자를 가리킵니다."}]},{"researchId":"JBC_GENESIS_06_08_WORBS_20261009_01","sourceSha256":"1883356ab6a2fe9dd5c334dc5479c08c2ef14ceafb0ec62952eb58f5890c8ff3","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"REVIEW_ONLY","externalRelease":"NOT_AUTHORIZED","title":"창세기 7장 — 물의 심판과 방주 안의 생명","passage":{"book":"gen","chapter":7,"v1":1,"v2":24,"ref":"창세기 7장"},"overview":["창세기 7장은 앞 장에서 선포된 심판과 보존의 말씀이 실제 사건으로 전개되는 장입니다. 하나님은 노아와 가족을 방주로 들이시고, 땅의 물과 하늘의 물이 쏟아지는 가운데 그들을 보존하십니다. 반복과 시간 표시는 홍수의 압도적인 힘뿐 아니라 하나님의 말씀과 노아의 순종이 끝까지 일치한다는 사실을 드러냅니다."],"centralMessage":"창세기 7장은 앞 장에서 선포된 심판과 보존의 말씀이 실제 사건으로 전개되는 장입니다. 하나님은 노아와 가족을 방주로 들이시고, 땅의 물과 하늘의 물이 쏟아지는 가운데 그들을 보존하십니다. 반복과 시간 표시는 홍수의 압도적인 힘뿐 아니라 하나님의 말씀과 노아의 순종이 끝까지 일치한다는 사실을 드러냅니다.","sections":[{"id":"gen7-1-5","v1":1,"v2":5,"title":"들어가라는 명령과 정결한 짐승","paragraphs":["하나님은 '너와 네 온 집은 방주로 들어가라'고 말씀하십니다. 6장에서 방주를 지으라는 명령을 받았던 노아가 이제 그 안으로 들어가라는 명령을 받습니다. 하나님의 '내 앞에서 의롭다'는 평가는 6:8–9의 은혜와 의로움의 소개를 이어받습니다. 노아가 자기 노력만으로 구원을 획득했다는 결론보다 하나님이 보신 삶의 방향과 주신 보존의 약속이 함께 전개된다는 점이 중요합니다.","2–3절의 정결한 짐승 '일곱씩 일곱씩, 수컷과 암컷'이라는 히브리어 표현은 일반적으로 일곱 쌍으로 이해되며, 부정한 짐승은 한 쌍으로 이해됩니다. 6:19–20의 암수 한 쌍은 생명 보존을 위한 기본 원칙을 말하고, 7장은 정결한 짐승의 추가 수량을 설명합니다. 8:20에서 노아가 정결한 짐승으로 번제를 드리는 장면은 이 구별이 서사에서 맡는 역할을 보여 줍니다. 모세 율법의 후대 세부 규정을 이 장면에 모두 소급할 수는 없습니다. 5절의 '명하신 대로 다 행하였더라'는 말은 6:22를 반복하여 말씀과 응답의 일치를 강조합니다."]},{"id":"gen7-6-16","v1":6,"v2":16,"title":"일곱 날의 기다림과 홍수의 시작","paragraphs":["노아의 나이 육백 세, 둘째 달 열이렛날이라는 날짜와 칠 일의 대기, 사십 주야의 비는 서사에 시간의 질서를 부여합니다. '큰 깊음의 샘들이 터지고 하늘의 창들이 열렸다'(11절)는 묘사는 땅 아래와 하늘 위에서 물이 쏟아지는 창조 세계의 전면적 동요를 그립니다. 창세기 1장의 물의 분리와 질서 형성을 떠올리면 이 장면은 생명이 살 수 있도록 마련된 공간이 다시 물에 잠기는 '창조 질서의 역전'으로 읽힙니다. 그러나 이 문학적 관찰만으로 고대의 물리적 구조나 현대 지질학적 세부를 확정할 수는 없습니다.","노아와 가족, 각 종류의 동물이 방주로 들어가는 과정이 반복해서 서술됩니다. 16절은 인간과 동물의 입장이 하나님의 명령대로 이루어졌다고 말한 뒤 '여호와께서 그를 닫아 넣으셨다'고 덧붙입니다. 마지막 동작은 노아의 순종만으로 사건이 완결되는 것이 아니라 생명의 보호가 하나님의 행동에 달려 있음을 보여 줍니다. 닫힌 문은 심판과 보존 사이의 서사적 경계이지만 이를 특정한 후대 신약 구절과 설명 없이 동일시할 필요는 없습니다."]},{"id":"gen7-17-24","v1":17,"v2":24,"title":"높아지는 물과 남겨진 생명","paragraphs":["17–20절에서는 물이 많아지고, 더욱 강해지고, 높은 산들까지 덮는 묘사가 단계적으로 심화됩니다. '강해지다/압도하다'를 뜻하는 גָּבַר(가바르)가 반복되어 물의 압도적인 세력을 표현합니다. 물이 방주를 떠오르게 하는 같은 장면에서 방주 밖의 땅은 생명의 거처를 잃습니다. 40일은 비가 내리는 기간으로, 150일은 물이 우세한 기간으로 서술됩니다. 두 숫자를 아무 설명 없이 더해 정확한 전체 홍수 일수로 확정하기보다 8장까지 이어지는 날짜 서술 안에서 읽어야 합니다.","21–23절은 죽음의 범위를 생물의 종류별로 반복하며 '지면의 모든 생물'이 쓸려 나갔다고 선언합니다. '오직 노아와 그와 함께 방주에 있던 자만 남았다'에서 '남다'(שָׁאַר, 샤아르)는 멸망의 범위와 대비되는 보존의 결과를 말합니다. 창세기는 땅 전체를 뒤덮는 보편적 심판의 언어를 사용합니다. 그 표현을 현대 지리 범위나 지질 연대의 모든 논쟁에 대한 단독 판결로 삼을 수는 없지만, 본문은 인간의 악에 대한 심판이 작은 불편이나 사소한 재난으로 축소될 수 없음을 강조합니다."]}],"discoveries":[{"id":"gen7-deep-0","domain":"theology","title":"더 깊은 연구","paragraphs":["홍수의 범위, 날짜 계산의 관계, 정결한 동물의 수량은 설명이 필요한 주제입니다. '일곱씩 일곱씩'을 번역할 때는 일반적인 암수 한 쌍의 규정과 정결한 동물에 관한 특별 규정을 함께 보아야 합니다. 40일과 150일을 독립된 연속 기간으로 단정하는 계산은 8:3–5의 시간 흐름과 대조해야 합니다. 고대 근동의 홍수 이야기와 공통된 모티프가 있더라도 창세기 6:11–13의 강포와 7장의 말씀·순종·보존 구조를 지워서는 안 됩니다."]},{"id":"gen7-deep-1","domain":"theology","title":"심화 설명","paragraphs":["마태복음 24:37–39는 노아의 때를 심판이 갑작스럽게 드러나는 때에 비유하고, 베드로후서 3:5–7은 물에 의한 옛 심판을 장차 있을 심판과 연결합니다. 히브리서 11:7은 노아가 아직 보이지 않는 일에 관한 경고를 받고 믿음으로 방주를 준비했다고 해석합니다. 베드로전서 3:20–21의 세례 연결은 후대 정경의 신학적 해석으로 존중하되 방주 자체가 세례의 모든 세부를 직접 설명한다고 말하지 않습니다."]},{"id":"gen7-deep-2","domain":"theology","title":"심화 설명","paragraphs":["중심 메시지: 하나님의 심판은 죄로 무너진 세계를 가볍게 여기지 않으며, 같은 하나님의 말씀은 방주 안의 생명을 끝까지 보존하여 새 출발의 가능성을 지킵니다."]},{"id":"gen7-deep-3","domain":"theology","title":"심화 설명","paragraphs":["---"]}],"lexicalCards":[{"verse":2,"form":"טָהוֹר","lemma":"טָהוֹר","transliteration":"","pronunciation":"타호르","gloss":"정결한","morphology":"본문 문맥에서 확인","note":"정결 동물의 수량과 후대 율법의 구분을 동일시하지 않습니다."},{"verse":6,"form":"מַבּוּל","lemma":"מַבּוּל","transliteration":"","pronunciation":"마불","gloss":"홍수","morphology":"본문 문맥에서 확인","note":"심판으로서의 홍수 사건을 가리킵니다."},{"verse":18,"form":"גָּבַר","lemma":"גָּבַר","transliteration":"","pronunciation":"가바르","gloss":"우세해지다·불어나다","morphology":"본문 문맥에서 확인","note":"물이 땅 위에 점점 강해지는 서술입니다."},{"verse":23,"form":"שָׁאַר","lemma":"שָׁאַר","transliteration":"","pronunciation":"샤아르","gloss":"남다","morphology":"본문 문맥에서 확인","note":"물의 심판 가운데 남겨진 생명을 강조합니다."}],"cautions":["정결 동물의 숫자 표현과 후대 레위기 제도를 단순 동일시하지 않습니다.","40일의 비와 150일의 물 지속 기간을 무조건 합산하지 않습니다.","고대 본문의 보편적 심판 표현을 현대 지질학의 범위 판정으로 직접 치환하지 않습니다."],"canonicalLinks":[{"ref":"히브리서 11:7","note":"노아의 방주 준비를 믿음의 관점에서 해석합니다."},{"ref":"마태복음 24:37–39","note":"예수께서 노아의 날을 심판과 준비의 교훈으로 언급하십니다."},{"ref":"베드로전서 3:20–21","note":"홍수 생존과 세례의 정경적 유비를 제공합니다."}]},{"researchId":"JBC_GENESIS_06_08_WORBS_20261009_01","sourceSha256":"1883356ab6a2fe9dd5c334dc5479c08c2ef14ceafb0ec62952eb58f5890c8ff3","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"REVIEW_ONLY","externalRelease":"NOT_AUTHORIZED","title":"창세기 8장 — 기억하시는 하나님과 다시 시작되는 땅","passage":{"book":"gen","chapter":8,"v1":1,"v2":22,"ref":"창세기 8장"},"overview":["창세기 8장의 전환점은 노아가 어떤 행동을 시작한 순간보다 '하나님이 노아와 모든 생물을 기억하셨다'는 선언입니다. 물은 물러가고 땅은 다시 드러나며 노아는 하나님의 말씀을 따라 방주에서 나옵니다. 새 땅에서 드린 제사와 계절의 지속에 대한 말씀은 인간의 마음이 여전히 악하다는 현실 속에서도 하나님이 창조 세계를 보존하신다는 긴장을 남깁니다."],"centralMessage":"창세기 8장의 전환점은 노아가 어떤 행동을 시작한 순간보다 '하나님이 노아와 모든 생물을 기억하셨다'는 선언입니다. 물은 물러가고 땅은 다시 드러나며 노아는 하나님의 말씀을 따라 방주에서 나옵니다. 새 땅에서 드린 제사와 계절의 지속에 대한 말씀은 인간의 마음이 여전히 악하다는 현실 속에서도 하나님이 창조 세계를 보존하신다는 긴장을 남깁니다.","sections":[{"id":"gen8-1-5","v1":1,"v2":5,"title":"하나님이 기억하시자 물이 물러간다","paragraphs":["7장은 물이 땅에 우세하다는 문장으로 끝났지만 8장은 '하나님이 기억하셨다'(וַיִּזְכֹּר, 바이즈코르)로 시작합니다. 성경에서 하나님이 기억하신다는 표현은 잊어버린 정보를 다시 떠올리셨다는 뜻에 머물지 않습니다. 하나님이 관계와 약속의 대상에게 실제로 돌봄의 행동을 시작하신다는 의미입니다. 기억의 대상은 노아뿐 아니라 방주 안의 짐승과 가축까지 포함합니다. 보존의 관심이 인간만이 아니라 피조 생명 전체를 향한다는 점이 중요합니다.","하나님이 땅 위에 바람(רוּחַ, 루아흐)을 지나가게 하시자 물이 줄어듭니다. 이 단어는 문맥에 따라 바람과 영을 가리킬 수 있으나 여기서는 물이 물러가는 과정과 직접 연결되는 '바람'이 자연스럽습니다. 창세기 1:2의 루아흐와 물의 장면을 함께 읽으면 새 창조의 울림이 생깁니다. 깊음의 샘과 하늘의 창이 닫히는 2절은 7:11에서 그것들이 열렸던 장면을 뒤집습니다. 생명이 살 수 있는 공간이 다시 나타나기 시작합니다.","4절은 방주가 '아라랏의 산들'(הָרֵי אֲרָרָט, 하레 아라라트)에 머물렀다고 말합니다. 이는 현대의 특정 아라랏 산 정상 하나를 지목하는 단수 표현이 아닙니다. 고대 지역 명칭과 산악 지대를 가리키는 본문을 존중하되 착륙한 정확한 봉우리·좌표·현대 관광지 위치를 확정하지 않습니다. 5절의 산봉우리들이 보이는 시점과 4절의 방주가 머문 시점은 서사상 구별되며 상세한 물리적 지형 재구성은 본문이 제공하지 않습니다."]},{"id":"gen8-6-14","v1":6,"v2":14,"title":"까마귀와 비둘기, 마른 땅을 확인하는 기다림","paragraphs":["노아는 창을 열어 까마귀를 내보내고 이어 비둘기를 반복해서 내보냅니다. 비둘기는 처음에는 발붙일 곳을 찾지 못해 돌아오고, 다시 나갔을 때는 감람나무의 새 잎을 물고 돌아오며, 마지막에는 돌아오지 않습니다. 새들의 움직임은 물이 줄어드는 과정을 단계적으로 확인하게 합니다. 감람나무 잎은 식생 회복의 징후이지만 잎 하나로 방주의 현대 위치나 비둘기의 비행 경로를 계산할 수는 없습니다.","서술은 물이 걷힌 상태와 땅이 완전히 마른 상태를 구분합니다. 노아가 눈으로 지면을 확인한 때(13절)와 하나님이 나오라고 명령하시는 때(15–16절) 사이에는 기다림이 있습니다. 관찰을 통해 상황을 파악하는 노아의 신중함과 새 출발의 최종 시점을 하나님의 말씀에 맡기는 태도가 나란히 놓입니다. 본문은 방주에서 벗어나는 것을 단순한 탈출의 성공으로 묘사하지 않습니다."]},{"id":"gen8-15-19","v1":15,"v2":19,"title":"방주에서 나오라는 말씀과 생명의 확장","paragraphs":["하나님은 가족과 모든 생물을 데리고 방주에서 나오라고 명하십니다. '나오다'(יָצָא, 야차) 동사가 명령과 실행에서 반복되어 7장에서의 '들어감'에 대응하는 전환을 만듭니다. 하나님이 들어가게 하셨던 방주에서 이제 하나님이 나오게 하십니다. 방주는 영구히 머물 안전지대가 아니라 생명을 보존하여 땅에서 다시 살아가게 하는 한시적 보호 공간입니다.","17절의 '생육하고 번성하라'는 말씀은 창세기 1장의 창조 복을 다시 떠올리게 합니다. 홍수 뒤의 세계는 이전 세계와 동일한 무죄의 에덴으로 돌아간 것이 아닙니다. 그러나 하나님은 생명에게 다시 땅에서 번성할 미래를 허락하십니다. 가족과 생물의 질서 있는 출현은 창조 세계가 완전히 포기되지 않았음을 보여 줍니다."]},{"id":"gen8-20-22","v1":20,"v2":22,"title":"제단, 향기, 그리고 멈추지 않을 계절","paragraphs":["방주에서 나온 노아의 첫 번째 기록된 행동은 여호와를 위한 제단을 쌓고 정결한 짐승과 새 가운데서 번제를 드리는 일입니다. '제단'(מִזְבֵּחַ, 미즈베아흐)과 '번제'(עֹלָה, 올라)는 예배와 감사의 응답을 나타냅니다. 이는 성경에서 제단 건축이 처음 명시되는 장면이지만 이전에 예배나 제단이 전혀 없었다는 증거는 아닙니다. '기쁘게 받으시는 향기'는 하나님이 제사를 받으시는 것을 감각 언어로 표현한 것입니다. 하나님이 음식이나 향기를 필요로 한다는 뜻은 아닙니다.","21절에는 중요한 역설이 있습니다. 6:5에서 인간 마음의 악한 계획은 심판의 이유였는데, 8:21에서는 인간 마음의 악이 여전하다는 사실이 언급되는 가운데 하나님은 다시는 이전과 같은 방식으로 모든 생명을 치지 않겠다고 결심하십니다. 사람의 본성이 갑자기 좋아져서 세계가 안정되는 것이 아닙니다. 하나님이 죄의 현실을 아시면서도 생명이 이어질 수 있도록 보존의 결단을 내리십니다. 이 결단은 9장에서 모든 생명과 맺으시는 언약으로 더 분명하게 선포됩니다.","22절의 '심음과 거둠, 추위와 더위, 여름과 겨울, 낮과 밤'은 피조 세계의 일상적 리듬을 열거합니다. 하나님은 땅이 존속하는 동안 이 질서가 끊어지지 않을 것이라고 말씀하십니다. 이는 자연재해가 전혀 일어나지 않는다는 보장이 아니라 인간의 악이 존재해도 세계가 다시 생명을 기를 수 있도록 하나님이 지속성을 부여하신다는 선언입니다. 심판 뒤에 남는 것은 인간에 대한 낙관이 아니라 창조주 하나님의 보존 의지입니다."]}],"discoveries":[{"id":"gen8-deep-0","domain":"theology","title":"더 깊은 연구","paragraphs":["아라랏은 고대의 산악 지역을 가리키는 표현으로 읽어야 하며 정확한 착륙 지점은 확인되지 않습니다. '기억하셨다'는 표현을 출애굽기 2:24의 언약 기억, 창세기 19:29의 아브라함 기억과 연결하면 하나님의 기억이 구체적 구원 행동으로 나타나는 패턴이 드러납니다. 루아흐의 바람/영이라는 가능성은 1:2와의 문학적 연결을 열어 주지만 8:1을 한 가지 교리적 표현으로 고정하지 않습니다."]},{"id":"gen8-deep-1","domain":"theology","title":"심화 설명","paragraphs":["이사야 54:9는 노아의 물과 하나님의 맹세를 회복 약속의 비유로 불러오고, 예레미야 33:20–26은 낮과 밤의 질서를 하나님의 신실하심을 말하는 언어로 사용합니다. 창세기 9장은 8:21–22의 보존 결단을 모든 생명과의 언약으로 발전시킵니다. 신약의 새 창조와 최종 심판은 이 장의 주제를 확장하지만, 8장의 제사를 후대 속죄 교리의 모든 세부와 동일시해서는 안 됩니다."]},{"id":"gen8-deep-2","domain":"theology","title":"심화 설명","paragraphs":["중심 메시지: 하나님은 심판의 물 가운데 보존된 생명을 기억하시고 다시 땅으로 이끄시며, 인간의 악이 계속되는 현실 속에서도 창조 세계가 생명을 이어 가도록 신실하게 붙드십니다."]},{"id":"gen8-deep-3","domain":"theology","title":"심화 설명","paragraphs":["---"]},{"id":"gen8-deep-4","domain":"theology","title":"심화 설명","paragraphs":["# Project01 내부 증거·관계·QA 데이터 — 독자 화면 비노출"]}],"lexicalCards":[{"verse":1,"form":"זָכַר","lemma":"זָכַר","transliteration":"","pronunciation":"자카르","gloss":"기억하다","morphology":"본문 문맥에서 확인","note":"하나님의 기억은 보존을 위한 행동으로 전환됩니다."},{"verse":1,"form":"רוּחַ","lemma":"רוּחַ","transliteration":"","pronunciation":"루아흐","gloss":"바람·영","morphology":"본문 문맥에서 확인","note":"본문에서는 물을 물러가게 하는 바람의 기능을 우선 봅니다."},{"verse":4,"form":"הָרֵי אֲרָרָט","lemma":"הָרֵי אֲרָרָט","transliteration":"","pronunciation":"하레 아라라트","gloss":"아라랏의 산들","morphology":"본문 문맥에서 확인","note":"복수 지형 표현으로 특정 현대 봉우리를 확정하지 않습니다."},{"verse":16,"form":"יָצָא","lemma":"יָצָא","transliteration":"","pronunciation":"야차","gloss":"나오다","morphology":"본문 문맥에서 확인","note":"방주에서 나오라는 하나님의 명령과 순종에 연결됩니다."},{"verse":20,"form":"מִזְבֵּחַ","lemma":"מִזְבֵּחַ","transliteration":"","pronunciation":"미즈베아흐","gloss":"제단","morphology":"본문 문맥에서 확인","note":"방주 이후 노아의 예배 행위를 가리킵니다."}],"cautions":["아라랏의 산들을 현대 특정 봉우리나 좌표로 단정하지 않습니다.","루아흐를 문맥 검토 없이 성령과 동일시하지 않습니다.","노아의 제사를 후대 속죄 교리와 모든 세부에서 등치시키지 않습니다."],"canonicalLinks":[{"ref":"출애굽기 2:24","note":"하나님의 기억이 구원 행동으로 이어집니다."},{"ref":"이사야 54:9","note":"노아의 물을 회복 언약의 언어로 재사용합니다."},{"ref":"창세기 9:8–17","note":"보존 결단이 모든 생명과의 언약으로 구체화됩니다."}]},{"researchId":"JBC_GENESIS_09_11_WORBS_20261009_01","sourceSha256":"b0c9cc02b25bac3c62c58f7d04e9b37e7a1eeaeb5690fb64f55e18962d46bfff","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"REVIEW_ONLY","externalRelease":"NOT_AUTHORIZED","title":"창세기 9장 — 생명의 경계와 언약","passage":{"book":"gen","chapter":9,"v1":1,"v2":29,"ref":"창세기 9장"},"overview":["홍수 이후 세계는 새로운 시작을 맞지만 에덴으로 되돌아가지는 않습니다. 하나님은 노아와 아들들에게 번성의 복을 주시고, 생명의 피를 함부로 취하지 못하게 하시며, 사람을 하나님의 형상으로 존중하도록 요구하십니다. 모든 생물과 맺으신 언약의 표징은 구름 속의 무지개입니다. 그러나 노아의 포도원 이야기는 새 세계에서도 인간의 연약함과 가족 안의 수치가 사라지지 않았음을 보여 줍니다."],"centralMessage":"홍수 이후 세계는 새로운 시작을 맞지만 에덴으로 되돌아가지는 않습니다. 하나님은 노아와 아들들에게 번성의 복을 주시고, 생명의 피를 함부로 취하지 못하게 하시며, 사람을 하나님의 형상으로 존중하도록 요구하십니다. 모든 생물과 맺으신 언약의 표징은 구름 속의 무지개입니다. 그러나 노아의 포도원 이야기는 새 세계에서도 인간의 연약함과 가족 안의 수치가 사라지지 않았음을 보여 줍니다.","sections":[{"id":"gen9-1-3","v1":1,"v2":3,"title":"창조의 복이 다시 주어지지만 관계는 달라진다","paragraphs":["하나님은 노아와 그의 아들들에게 “생육하고 번성하여 땅에 충만하라”고 복을 주십니다. 이는 창세기 1:28을 떠올리게 합니다. 홍수는 죄에 대한 심판이었지만 생명을 향한 창조주의 뜻을 철회한 사건이 아니었습니다. 8:17에서 동물에게도 번성이 언급되고 9:1에서는 사람에게 같은 복이 선포됩니다.","그러나 2절에서 동물들이 사람을 두려워한다는 설명은 창세기 1장의 평화로운 묘사와 다릅니다. 3절은 살아 움직이는 것을 먹을거리로 허락하면서도 바로 뒤에 제한을 둡니다. 허락과 경계가 함께 제시된다는 점에서 2:16–17과 비교할 수 있습니다. 하나님이 생존을 위한 자원을 주셨다고 해서 생명을 무제한으로 처분할 권리를 주신 것은 아닙니다."]},{"id":"gen9-4-7","v1":4,"v2":7,"title":"피와 하나님의 형상: 생명은 소유물이 아니다","paragraphs":["4절의 “생명 되는 피”는 히브리어 נֶפֶשׁ(네페쉬, 생명·살아 있는 존재)와 דָּם(담, 피)이 연결된 표현입니다. 피를 금하는 이유는 피를 마술적 물질로 보아서가 아니라 살아 있는 존재의 생명이 함부로 취할 수 없는 것임을 밝히기 때문입니다. 레위기 17:11은 후대 이스라엘 제사법 안에서 피와 생명의 관계를 더 분명히 설명합니다. 창세기 9:4가 곧바로 그리스도의 보혈을 직접 예언한다고 단정하는 것은 본문을 앞질러 가는 해석입니다.","5–6절은 짐승과 사람 모두에게 사람의 피에 대한 책임을 묻는다는 언어로 인간 생명의 특별한 존엄을 강조합니다. 6절은 “피를 흘리다/피가 흘려지다”를 대칭적으로 배열하고 그 이유를 “하나님이 자기 형상대로 사람을 지으셨기 때문”이라고 밝힙니다. צֶלֶם(첼렘, 형상)은 창세기 1:26–27과 연결됩니다. 죄와 심판 이후에도 인간이 하나님의 형상이라는 근거는 사라지지 않습니다. 이 구절이 살인 금지와 책임을 엄중히 선언한다는 사실은 분명하지만, 이를 곧바로 현대의 특정 형벌제도 전체에 대한 단일 법률 지침으로 환원하려면 별도의 법·정경 연구가 필요합니다. 7절의 번성 명령이 단락을 닫습니다. 하나님은 피를 흘리는 파괴가 아니라 생명을 낳고 보존하는 세계를 명하십니다."]},{"id":"gen9-8-17","v1":8,"v2":17,"title":"하나님이 세우시고 기억하시는 모든 생명의 언약","paragraphs":["6:18에서 예고되고 8:21–22에서 방향이 드러난 약속이 여기서 확장됩니다. בְּרִית(베리트, 언약)의 상대는 노아 가족에 그치지 않고 후손과 방주에서 나온 모든 생물, 곧 땅의 생명 전체입니다. 하나님이 “내 언약을 세우리라”고 거듭 말씀하시는 קוּם(쿰, 서다·세우다) 계열 동사는 이전 약속을 실제로 확증하는 행동을 나타냅니다. 언약의 핵심은 다시는 홍수로 모든 육체를 멸하지 않겠다는 약속이지, 이후 어떤 심판이나 재난도 없으리라는 선언은 아닙니다.","13절의 קֶשֶׁת(케셰트)는 무지개이면서 활을 뜻합니다. 전쟁의 활을 내려놓는 평화의 상징으로 읽을 여지는 있으며, 고대 근동의 무장한 신상들과 비교할 때 의미 있는 해석입니다. 그러나 본문이 활을 꺾었다거나 특정 방향으로 걸었다고 직접 설명하지는 않습니다. 본문이 반복하는 확실한 의미는 하나님과 모든 생명 사이에 세우신 언약의 표징이라는 사실입니다. “내가 보고 기억하리라”는 표현도 하나님이 잊지 않기 위해 기억 보조물이 필요하다는 뜻보다, 자신이 맺은 관계와 약속에 따라 행동하시겠다는 신뢰의 언어입니다. 8:1에서 노아와 생물을 기억하셨던 하나님이 이제 모든 세대를 향한 보존의 약속을 명시하십니다."]},{"id":"gen9-18-23","v1":18,"v2":23,"title":"노아의 수치와 가족의 서로 다른 반응","paragraphs":["18–19절은 셈·함·야벳을 다시 소개하며 다음 장의 민족 계보로 이어지는 다리를 놓습니다. 노아는 땅을 경작하고 포도원을 심습니다. 홍수 이전에 의로운 사람으로 소개되었던 그가 포도주에 취하여 장막 안에서 벌거벗은 모습으로 나타납니다. 새로운 세계에 들어왔다고 해서 인간이 죄와 취약성에서 자동으로 벗어나지 않았다는 서사적 반전입니다. 창세기 2:25의 부끄러움 없는 벌거벗음과 달리 여기서는 가족 안에서 수치가 문제가 됩니다.","함은 아버지의 벌거벗음을 보고 밖에 있는 두 형제에게 알립니다. 셈과 야벳은 옷을 어깨에 메고 뒷걸음질하여 들어가 아버지를 덮되 그의 벌거벗음을 보지 않습니다. 본문은 두 행동을 분명히 대비합니다. 함의 행동이 단순한 구경과 수치의 확산인지, 더 중대한 침해를 암시하는지에는 논쟁이 있습니다. 22–23절이 명시하는 행동을 넘어 확정적 범죄 장면을 새로 만들지 않는 것이 타당합니다. 핵심은 타인의 수치 앞에서 취하는 태도가 가족의 미래에 중대한 긴장을 일으켰다는 데 있습니다."]},{"id":"gen9-24-29","v1":24,"v2":29,"title":"가나안에게 향한 저주와 풀리지 않은 긴장","paragraphs":["노아가 깨어난 뒤 발한 말은 함 자신이 아니라 함의 아들 가나안에게 저주를 선언합니다. 본문을 ‘함의 모든 후손이 저주받았다’고 바꾸거나 피부색·대륙·현대 민족의 서열을 정하는 근거로 삼을 수 없습니다. 가나안이 왜 아버지의 행동에 연결되어 저주의 대상으로 나타나는지는 본문이 명확히 설명하지 않습니다. 10장에 가나안 계열의 민족들이 등장하는 사실은 서사적 연결을 보여 주지만, 개인의 책임과 후손의 운명 사이의 문제를 자동으로 해결하지는 않습니다.","26절의 축복 문장은 셈에게 직접 복을 주기보다 “셈의 하나님 여호와를 찬송하리로다”라고 하나님을 높입니다. 27절에서 야벳이 넓어지고 셈의 장막에 거한다는 표현의 주어와 함의는 논의가 있습니다. 이를 현대 국가나 인종의 지배를 보증하는 예언으로 확정할 수 없습니다. 28–29절은 노아의 나이와 죽음을 기록하여 홍수 서사를 마무리합니다. 은혜와 언약의 주인공도 죽음의 현실 밖에 있지 않습니다. 새 출발의 소망은 인간 영웅의 무결성이 아니라 언약을 지키시는 하나님에게 있습니다."]}],"discoveries":[{"id":"gen9-deep-0","domain":"theology","title":"더 깊은 연구","paragraphs":["이 장의 문학적 배열은 생명을 향한 하나님의 복(1–7절) → 모든 생명을 향한 하나님의 언약(8–17절) → 한 가족 안의 수치와 갈등(18–29절)입니다. 보편적 언약이 선언된 뒤 인간의 결함이 드러난다는 배열은 8:21의 인간 마음에 관한 진술과 맞물립니다. 언약은 인간이 완전해졌기 때문에 유지되는 계약이 아니라 죄를 아시는 하나님이 피조 세계를 보존하시겠다고 선언하신 약속입니다."]},{"id":"gen9-deep-1","domain":"theology","title":"심화 설명","paragraphs":["무지개를 활로 읽는 상징적 해석, 함의 행동의 성격, 가나안 저주의 이유, 야벳이 셈의 장막에 거한다는 문장의 주어는 해석의 여지를 남깁니다. 이 장을 인종 차별이나 노예제의 근거로 삼는 것은 지칭 대상과 본문 목적을 왜곡합니다. 이사야 54:9–10은 노아의 물에 관한 하나님의 약속을 회복의 신실하심에 연결합니다. 베드로후서 3:5–13은 옛 물의 심판과 미래의 심판·새 창조를 구분합니다. 요한계시록 4:3의 무지개는 하나님 보좌의 영광을 묘사하지만, 창세기 9장의 표징을 그대로 다른 장면에 기계적으로 옮기는 것은 아닙니다."]},{"id":"gen9-deep-2","domain":"theology","title":"심화 설명","paragraphs":["중심 메시지: 하나님은 홍수 뒤에도 인간과 동물의 생명을 귀하게 여기시고, 죄가 남아 있는 세계를 향해 모든 생명을 보존하실 언약을 세우십니다. 인간의 연약함은 드러나지만 생명의 미래를 붙드는 근거는 하나님의 신실하심입니다."]},{"id":"gen9-deep-3","domain":"theology","title":"심화 설명","paragraphs":["---"]}],"lexicalCards":[{"verse":1,"form":"פָּרָה","lemma":"פָּרָה","transliteration":"","pronunciation":"파라","gloss":"번성하다","morphology":"본문 문맥","note":"번성하라는 창조의 복이 홍수 이후 반복됩니다. 명령과 복의 관계를 함께 읽습니다."},{"verse":4,"form":"נֶפֶשׁ","lemma":"נֶפֶשׁ","transliteration":"","pronunciation":"네페쉬","gloss":"생명","morphology":"본문 문맥","note":"생명과 피를 결합하여 살해·섭취 제한의 이유를 밝힙니다. ‘영혼’만으로 축소하지 않습니다."},{"verse":6,"form":"צֶלֶם","lemma":"צֶלֶם","transliteration":"","pronunciation":"첼렘","gloss":"형상","morphology":"본문 문맥","note":"하나님의 형상이 살인 금지의 신학적 근거입니다."},{"verse":9,"form":"בְּרִית","lemma":"בְּרִית","transliteration":"","pronunciation":"베리트","gloss":"언약","morphology":"본문 문맥","note":"하나님이 약속을 세우고 확증하시는 행위의 반복."},{"verse":13,"form":"קֶשֶׁת","lemma":"קֶשֶׁת","transliteration":"","pronunciation":"케셰트","gloss":"활·무지개","morphology":"본문 문맥","note":"활/무지개 의미가 표징 해석을 넓히지만 ‘무장 해제’는 가능 해석입니다."},{"verse":25,"form":"אָרוּר","lemma":"אָרוּר","transliteration":"","pronunciation":"아루르","gloss":"저주받은","morphology":"본문 문맥","note":"저주 선언의 직접 대상은 가나안입니다."}],"cautions":["9:25의 저주를 함 전체나 현대 인종에 확대하지 않습니다.","무지개의 활 상징을 하나님이 활을 꺾었다는 직접 진술로 단정하지 않습니다."],"canonicalLinks":[{"ref":"창 1:26–28","note":"홍수 후에도 존엄의 근거와 번성의 사명이 유지됩니다."},{"ref":"레 17:11","note":"창 9장의 생명 존중이 율법 안에서 확장되는 방향을 보여 줍니다."},{"ref":"사 54:9–10","note":"자연 보존 약속이 이스라엘 회복의 신뢰 언어로 재사용됩니다."},{"ref":"벧후 3:5–13","note":"노아 언약을 모든 심판의 영구 폐지로 읽지 않게 합니다."}]},{"researchId":"JBC_GENESIS_09_11_WORBS_20261009_01","sourceSha256":"b0c9cc02b25bac3c62c58f7d04e9b37e7a1eeaeb5690fb64f55e18962d46bfff","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"REVIEW_ONLY","externalRelease":"NOT_AUTHORIZED","title":"창세기 10장 — 여러 언어와 땅으로 펼쳐진 한 인류의 세계","passage":{"book":"gen","chapter":10,"v1":1,"v2":32,"ref":"창세기 10장"},"overview":["창세기 10장은 노아의 세 아들에서 이어지는 가족과 민족, 도시와 지역의 분포를 보여 주는 이른바 ‘민족들의 표’입니다. 이름이 연속되지만 단순한 명단이 아닙니다. 홍수 후 생육하고 번성하라는 복이 실제 세계의 다양성으로 전개되고, 사람들은 언어와 땅과 족속에 따라 살아가게 됩니다. 동시에 특정 도시와 권력의 성장, 가나안 지역의 경계, 셈 계열의 계보가 등장하여 바벨 이야기와 아브람의 부르심을 준비합니다. 이 목록은 고대 성경 세계의 시야로 그려진 민족·지리의 문학적 지도이지 오늘날 모든 국민국가의 생물학적 기원표가 아닙니다."],"centralMessage":"창세기 10장은 노아의 세 아들에서 이어지는 가족과 민족, 도시와 지역의 분포를 보여 주는 이른바 ‘민족들의 표’입니다. 이름이 연속되지만 단순한 명단이 아닙니다. 홍수 후 생육하고 번성하라는 복이 실제 세계의 다양성으로 전개되고, 사람들은 언어와 땅과 족속에 따라 살아가게 됩니다. 동시에 특정 도시와 권력의 성장, 가나안 지역의 경계, 셈 계열의 계보가 등장하여 바벨 이야기와 아브람의 부르심을 준비합니다. 이 목록은 고대 성경 세계의 시야로 그려진 민족·지리의 문학적 지도이지 오늘날 모든 국민국가의 생물학적 기원표가 아닙니다.","sections":[{"id":"gen10-1-5","v1":1,"v2":5,"title":"야벳의 후손과 바다 건너 지역","paragraphs":["1절의 “노아의 아들들의 족보”는 תּוֹלְדֹת(톨레도트, 계보·내력)라는 창세기 특유의 표제로 새로운 단위를 엽니다. 9장에서 노아의 가족이 다시 소개된 뒤, 이제 시야가 그 가족에서 세계로 확장됩니다. 야벳 계열의 고멜, 마곡, 마대, 야완 등은 고대 독자에게 알려진 북방·서방 및 해상 지역과 연관되어 이해되었습니다. 예를 들어 야완은 이오니아·그리스권, 마대는 메대와 연결되는 경우가 많지만, 모든 이름을 현대 국가나 민족과 일대일로 대응시킬 수는 없습니다.","5절은 “그들의 땅에서 각각 언어와 종족과 나라대로” 나뉘었다고 말합니다. גּוֹיִם(고임, 민족들), לָשׁוֹן(라숀, 혀·언어), מִשְׁפָּחָה(미쉬파하, 씨족·가족 집단), אֶרֶץ(에레츠, 땅·지역)은 목록의 분류 기준을 보여 줍니다. 이 표현은 20절과 31절에서 다시 나타납니다. 하나의 계보가 다양한 언어와 문화, 거주 지역으로 펼쳐지는 것은 9:1의 번성 명령이 역사 속에 드러나는 방식입니다. 이 절은 곧바로 11:1의 ‘온 땅의 언어가 하나’라는 서술과 시간적 긴장을 만들며, 11장은 그 분화에 관한 앞선 사건을 이야기로 되짚는 것으로 읽는 해석이 유력합니다."]},{"id":"gen10-6-12","v1":6,"v2":12,"title":"함의 후손과 도시 권력의 등장","paragraphs":["함의 아들로 구스, 미스라임, 붓, 가나안이 열거됩니다. 미스라임은 히브리어에서 애굽을 가리키는 통상적인 명칭입니다. 구스와 붓의 지리적 범위 및 세부 후손의 동일시는 각 이름마다 확실성이 다릅니다. 현대 인종 범주를 이 족보에 그대로 투사해서는 안 됩니다. 가나안이 함 계열에 놓이는 서술은 앞 장의 가나안 저주와 연결되지만, 현대의 특정 인종을 평가하는 틀을 제공하지 않습니다.","8–12절에서는 님롯에 대한 서술이 잠시 족보 형식을 벗어나 ‘땅에서 처음으로 강한 자’와 ‘용감한 사냥꾼’이라는 특징, 왕국과 도시들을 제시합니다. גִּבּוֹר(기보르)는 힘 있는 자·용사를 뜻하며, 님롯의 능력과 권력의 이미지를 드러냅니다. 바벨, 에렉, 악갓과 시날의 도시들은 메소포타미아의 정치·도시적 세계를 불러옵니다. 11–12절에서 앗수르로 나간 주체가 님롯인지, ‘앗수르’라는 인물·지역 주어인지에는 문법상 논의가 있습니다. 님롯을 바벨탑의 건축 책임자로 지목하거나 특정 역사적 왕과 동일인이라고 확정하는 것은 본문이 직접 말하는 범위를 넘습니다. 다만 바벨이 10장에 도시 이름으로 등장한 뒤 11장에서 인간의 집중과 흩어짐의 장소로 다시 등장하는 연결은 분명합니다."]},{"id":"gen10-13-20","v1":13,"v2":20,"title":"애굽·가나안의 계열과 본문이 말하는 경계","paragraphs":["13–14절은 애굽과 연결된 여러 집단을 열거하며 블레셋 사람의 기원을 언급합니다. 이 절의 ‘가슬루힘에게서 블레셋이 나왔다’는 문장 위치와 갑돌 관련 구절(암 9:7; 렘 47:4)을 함께 읽을 때, 정확한 출발 집단과 이동 과정을 단순하게 확정하기 어렵습니다. 본문은 계열을 제공하지만 연대·이주 경로·정착 순서를 상세히 기록하지 않습니다.","15–18절의 가나안 후손 명단에는 시돈, 헷과 여러 지역 집단이 등장합니다. 19절은 시돈에서 그랄·가사 쪽으로, 또 소돔·고모라·아드마·스보임과 라사 쪽으로 가나안의 경계를 서술합니다. 여기서 גְּבוּל(게불, 경계·영역)은 본문이 인식하는 거주 범위를 가리키지만, 나열된 지명을 모두 현대 지도에 정확히 배치하거나 그 사이에 단일한 직선 경계를 그릴 근거는 아닙니다. 그랄·가사 등은 후대 족장 이야기와 연결되지만, 특히 소돔·고모라와 라사의 정확한 위치는 별도의 검증이 필요합니다. 따라서 이 구절은 지리 관계를 설명하는 문헌 근거로 우선 보존해야 합니다."]},{"id":"gen10-21-31","v1":21,"v2":31,"title":"셈의 계열, 에벨, 벨렉과 욕단","paragraphs":["셈의 계보는 에벨과 그 후손으로 초점을 좁히며 11:10–26의 직계 계보를 준비합니다. 21절에서 셈은 ‘에벨의 모든 자손의 조상’으로 소개됩니다. 에벨을 ‘히브리인’ 명칭과 연결하는 해석은 가능하지만, 음성의 유사성만으로 모든 역사적 어원을 확정할 수는 없습니다. 엘람·앗수르·아르박삿·룻·아람 등은 앞선 두 계열과 마찬가지로 인물·집단·지리 명칭이 뒤섞인 족보의 성격을 보여 줍니다. 고대 족보는 생물학적 혈통만을 기록하는 현대 가족관계 등록부와 다릅니다.","25절은 벨렉의 때에 땅이 ‘나뉘었다’고 설명합니다. פָּלַג(팔라그, 나누다) 계열의 말은 벨렉이라는 이름과 연결된 언어유희로 읽힙니다. 11장의 언어 분산과 연결하는 해석이 자연스럽지만, 본문이 정확한 사건 날짜나 대륙의 지각 분열을 가리킨다고 단정할 수는 없습니다. 욕단의 후손들과 30절의 거주지 범위도 아라비아 등과 연관하여 연구되지만, 메사와 스발의 정확한 현대 위치 및 경로는 확정되지 않았습니다. 이 목록의 목적은 모든 위치를 계산하는 것보다 한 가족에서 여러 지역 공동체로 퍼진 세계를 보여 주는 데 있습니다."]},{"id":"gen10-32-32","v1":32,"v2":32,"title":"세계의 다양성과 다음 이야기로의 연결","paragraphs":["마지막 절은 “홍수 후에 이들에게서 그 땅의 나라들이 나뉘었다”고 요약합니다. 1절과 32절이 서로를 감싸고, 야벳·함·셈의 세 부분은 각각 언어·족속·땅·나라의 공식으로 마무리됩니다. 10장의 배열은 9:1의 번성의 복을 보여 주면서도 11:1–9의 바벨 이야기를 기다리게 합니다. 이미 여러 언어가 기록된 뒤 하나의 언어를 말하는 11장은 단순한 연대기적 다음 단계보다, 세계의 분산을 설명하기 위해 앞선 시점을 다시 조명하는 문학적 배열로 이해할 수 있습니다. 모든 사람이 실제로 같은 혈통 계보표에 완전하게 수록되었다는 뜻은 아닙니다."]}],"discoveries":[{"id":"gen10-deep-0","domain":"theology","title":"더 깊은 연구","paragraphs":["민족들의 표는 ‘약 70개 민족’이라는 전통적 설명으로 널리 알려져 있으나, 이름의 집계 방식과 본문 전승에 따라 수가 달라질 수 있으므로 이를 정확한 현대 민족 수로 확정하지 않습니다. 같은 이름이 인물·도시·지역·집단을 가리킬 수 있으며, 족보상의 ‘아들’은 더 넓은 후손 관계를 나타낼 수 있습니다. 님롯의 역사적 동일시, 10:11의 주어, 벨렉 시대의 분리, 10:19의 경계 및 여러 해안·내륙 지명은 각기 다른 수준의 불확실성을 갖습니다."]},{"id":"gen10-deep-1","domain":"theology","title":"심화 설명","paragraphs":["역대상 1:5–23은 이 목록을 다시 전하며 이스라엘의 역사를 더 넓은 인류의 계보 안에 놓습니다. 사도행전 17:26은 모든 민족이 한 근원에서 나왔음을 말하며, 민족의 차이가 인간의 존엄에 위계를 만들지 않는다는 정경적 의미를 더합니다. 이사야 19:23–25는 애굽·앗수르·이스라엘이 함께 하나님의 복에 참여하는 전망을 제시하여 창세기 10장의 지리적 다양성을 미래의 화해라는 관점에서 다시 보게 합니다. 요한계시록 7:9은 모든 나라·족속·백성·언어가 하나님을 예배하는 장면을 그리지만, 창세기 10장의 개별 이름들을 현대 국가와 일대일로 대응시키지는 않습니다."]},{"id":"gen10-deep-2","domain":"theology","title":"심화 설명","paragraphs":["중심 메시지: 홍수 뒤 하나님의 번성의 복은 다양한 언어·지역·공동체로 펼쳐집니다. 성경은 민족의 차이를 절대적 우열의 근거로 삼지 않고, 여러 민족이 함께 살아가는 세계에서 이어질 하나님의 역사와 약속을 준비합니다."]},{"id":"gen10-deep-3","domain":"theology","title":"심화 설명","paragraphs":["---"]}],"lexicalCards":[{"verse":1,"form":"תּוֹלְדֹת","lemma":"תּוֹלְדֹת","transliteration":"","pronunciation":"톨레도트","gloss":"계보·족보","morphology":"본문 문맥","note":"족보 표제로 서사 단위가 바뀝니다."},{"verse":5,"form":"גּוֹי","lemma":"גּוֹי","transliteration":"","pronunciation":"고이","gloss":"민족","morphology":"본문 문맥","note":"민족·언어·씨족이라는 분류 공식이 세 계열을 묶습니다."},{"verse":5,"form":"פָּרַד","lemma":"פָּרַד","transliteration":"","pronunciation":"파라드","gloss":"나뉘다·분리되다","morphology":"본문 문맥","note":"집단의 분화·나뉨. 11장의 흩어짐과 어근은 구별합니다."},{"verse":8,"form":"גִּבּוֹר","lemma":"גִּבּוֹר","transliteration":"","pronunciation":"기보르","gloss":"용사·강한 자","morphology":"본문 문맥","note":"님롯의 용사·권력 이미지. 구체 왕과 동일시하지 않습니다."},{"verse":19,"form":"גְּבוּל","lemma":"גְּבוּל","transliteration":"","pronunciation":"게불","gloss":"경계·영역","morphology":"본문 문맥","note":"문헌상의 가나안 경계·영역이지 정밀 GIS 선형 좌표가 아닙니다."},{"verse":25,"form":"פָּלַג","lemma":"פָּלַג","transliteration":"","pronunciation":"팔라그","gloss":"나누다","morphology":"본문 문맥","note":"벨렉과 ‘나뉨’의 이름 말놀이. 지각 분열로 단정하지 않습니다."}],"cautions":["족보를 오늘날 세계 모든 민족의 완전한 명단으로 단정하지 않습니다.","10:11의 주어와 님롯의 역사적 신원은 논쟁적입니다.","10:19의 경계를 정밀 지도 좌표로 전환하지 않습니다."],"canonicalLinks":[{"ref":"대상 1:5–23","note":"이스라엘의 역사를 인류 전체의 맥락 안에 놓습니다."},{"ref":"행 17:26","note":"민족 구분을 인간 존엄의 위계로 해석하지 않도록 돕습니다."},{"ref":"사 19:23–25","note":"분리된 지역 공동체를 향한 미래의 화해를 조명합니다."},{"ref":"계 7:9","note":"다양성의 소멸이 아니라 공동 예배의 미래를 보여 줍니다."}]},{"researchId":"JBC_GENESIS_09_11_WORBS_20261009_01","sourceSha256":"b0c9cc02b25bac3c62c58f7d04e9b37e7a1eeaeb5690fb64f55e18962d46bfff","projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"REVIEW_ONLY","externalRelease":"NOT_AUTHORIZED","title":"창세기 11장 — 자기 이름을 세우려는 도시에서 약속을 기다리는 가족으로","passage":{"book":"gen","chapter":11,"v1":1,"v2":32,"ref":"창세기 11장"},"overview":["창세기 11장은 인류의 넓은 세계를 보여 준 10장 뒤에서 한 언어를 사용하던 사람들의 도시 건설과 흩어짐을 서술합니다. 사람들은 시날에 정착하여 하늘에 닿는 탑과 성을 쌓고 자기 이름을 내려 하지만, 하나님은 그들의 언어를 혼잡하게 하여 흩으십니다. 뒤따르는 셈의 계보는 많은 민족 가운데 한 가족으로 초점을 좁힙니다. 마지막에는 가나안으로 가려던 데라의 가족이 하란에 머물고 사래는 자녀를 낳지 못하는 현실이 제시됩니다. 인류가 자기 이름을 만들려는 이야기 뒤에 하나님이 아브람에게 복을 주시고 그의 이름을 크게 하실 약속(12:2)이 이어집니다."],"centralMessage":"창세기 11장은 인류의 넓은 세계를 보여 준 10장 뒤에서 한 언어를 사용하던 사람들의 도시 건설과 흩어짐을 서술합니다. 사람들은 시날에 정착하여 하늘에 닿는 탑과 성을 쌓고 자기 이름을 내려 하지만, 하나님은 그들의 언어를 혼잡하게 하여 흩으십니다. 뒤따르는 셈의 계보는 많은 민족 가운데 한 가족으로 초점을 좁힙니다. 마지막에는 가나안으로 가려던 데라의 가족이 하란에 머물고 사래는 자녀를 낳지 못하는 현실이 제시됩니다. 인류가 자기 이름을 만들려는 이야기 뒤에 하나님이 아브람에게 복을 주시고 그의 이름을 크게 하실 약속(12:2)이 이어집니다.","sections":[{"id":"gen11-1-4","v1":1,"v2":4,"title":"하나의 언어, 함께 세우려는 도시와 이름","paragraphs":["1절의 שָׂפָה אֶחָת(사파 에하트, 한 입술·한 언어)와 דְּבָרִים אֲחָדִים(데바림 아하딤, 같은 말들)는 사람들 사이의 의사소통과 공동 행동의 가능성을 보여 줍니다. 10장에서는 이미 여러 언어가 나타났으므로, 11:1–9를 그 분화의 앞선 원인을 설명하는 회고적 이야기로 보는 독법이 설득력 있습니다. 다만 고대 세계에 공통 교역 언어가 있었을 가능성을 바탕으로 두 장을 조화시키려는 견해도 있습니다. 본문 자체는 특정 고대 언어의 이름이나 역사적 연대를 밝히지 않습니다.","2절의 이동 방향을 나타내는 히브리어 מִקֶּדֶם(미케뎀)은 ‘동쪽에서’ 또는 ‘동쪽으로’라는 번역 논의가 있습니다. 확실한 것은 사람들이 시날 땅의 평지를 발견하고 그곳에 거주했다는 점입니다. 시날은 메소포타미아, 특히 바빌로니아 지역과 연결되는 성경적 명칭이지만 이 구절만으로 정확한 탑의 위치를 지정할 수 없습니다. 3절의 구운 벽돌과 역청은 메소포타미아의 건축 환경을 이해하는 데 실제 도움이 됩니다. 돌보다 흙벽돌이 흔한 평야에서 구운 벽돌과 역청을 사용하는 기술은 집단적 건설을 가능하게 합니다. 본문은 기술 자체를 죄라고 부르지 않습니다.","4절의 “자, 성과 대를 쌓아 그 꼭대기를 하늘에 닿게 하여 우리 이름을 내고 온 지면에 흩어짐을 면하자”는 말은 건설의 목적을 밝힙니다. מִגְדָּל(미그달, 탑)은 높고 방어적·상징적인 구조물을 뜻하며, 메소포타미아 지구라트가 유익한 비교 배경이 될 수 있습니다. 그러나 본문은 특정 발굴된 지구라트가 곧 이 탑이라고 말하지 않습니다. ‘꼭대기가 하늘에 닿는다’는 말은 거대한 높이를 표현하는 관용적 과장일 수 있다(신 1:28). 핵심은 건축 규모만이 아니라 자기 이름을 확보하고 흩어짐을 피하려는 공동의 의도입니다. 9:1과 10:32의 땅에 퍼지는 세계와 비교하면 집중과 통제를 향한 인간의 욕망이 더욱 뚜렷해집니다."]},{"id":"gen11-5-9","v1":5,"v2":9,"title":"내려오시는 하나님과 뒤집힌 인간의 계획","paragraphs":["사람들은 탑을 하늘까지 높이려 하지만, 5절은 하나님이 그 성과 탑을 “보려고 내려오셨다”고 말합니다. יָרַד(야라드, 내려오다)의 서술은 하늘을 향한 인간의 거대한 계획을 상대화하는 문학적 반어입니다. 동시에 6절은 인간의 협력과 계획이 실제 힘을 지니고 있음을 인정합니다. 하나님은 단순히 건축물을 미워하시는 것이 아니라 한 언어로 결집된 사람들이 스스로 한계를 넘어서는 방향으로 계속 나아가는 것을 막으십니다.","3–4절에서 사람들이 반복한 “자, 우리가 … 하자”에 7절에서는 하나님이 “자, 우리가 내려가서 … 하자”로 응답하십니다. 인간의 의도와 하나님의 행위가 서로 마주 섭니다. 7절의 בָּלַל(발랄, 섞다·혼잡하게 하다)과 8–9절의 פּוּץ(푸츠, 흩어지다·흩다)는 사람들이 피하려 했던 흩어짐이 실제로 일어났음을 보여 줍니다. 이 사건의 결과로 성의 건설은 중단됩니다. 탑만이 아니라 ‘성’을 거듭 언급한다는 사실은 인간의 집중된 도시 공동체와 자기 보존의 구상이 심판의 대상이라는 점을 드러냅니다.","9절은 바벨이라는 이름을 발랄과 연결하는 히브리어 언어유희로 끝납니다. 이는 이야기 속 신학적 설명이지 바빌론이라는 도시명의 아카드어 어원을 그대로 설명하는 언어학적 공식은 아닙니다. 바벨의 도시 이름은 10:10에서 이미 등장했고, 이후 성경에서는 교만한 제국의 상징으로 발전합니다. 하나님이 언어를 혼잡하게 하신 일을 문화·언어 다양성 자체에 대한 영원한 저주라고 단정할 수는 없습니다. 여기서 문제는 언어의 존재보다 그 언어로 이루려는 인간의 목적입니다."]},{"id":"gen11-10-26","v1":10,"v2":26,"title":"셈의 직계 계보와 좁아지는 서사의 초점","paragraphs":["10절의 “셈의 족보”는 다시 תּוֹלְדֹת(톨레도트) 표제를 사용합니다. 10장의 넓은 분지형 민족 목록과 달리 11:10–26은 셈에서 아르박삿·셀라·에벨·벨렉·르우·스룩·나홀·데라로 이어지는 직계 계보에 집중합니다. 아버지가 몇 세에 아들을 낳았고 그 뒤 몇 년을 더 살았는지 반복하는 형식은 창세기 5장의 아담 계보와 닮았습니다. 홍수와 바벨을 거친 뒤에도 세대가 이어진다는 사실이 이야기의 중요한 움직임입니다. 족보는 흩어진 세계에서 하나님이 어떤 가족을 통해 다음 이야기를 전개하실지 독자의 시선을 좁힙니다.","이 계보의 연령 수치는 마소라 본문, 칠십인역, 사마리아오경 사이에 차이가 있습니다. 특히 칠십인역 전승과 누가복음 3:36의 가이난은 마소라 본문 창세기 11장의 명단과 비교할 때 별도 설명이 필요합니다. 따라서 한 전승의 숫자를 단순히 더하여 모든 고대사의 절대 연대를 확정하는 것은 신중해야 합니다. 본문의 주된 역할은 상세 연대표보다 세대의 연속성과 아브람으로 좁혀지는 계보의 방향에 있습니다."]},{"id":"gen11-27-32","v1":27,"v2":32,"title":"데라의 가족, 사래의 불임, 목적지에 이르지 못한 여정","paragraphs":["27절의 “데라의 족보”는 새로운 이야기의 문을 엽니다. 데라는 아브람·나홀·하란의 아버지이며, 하란이라는 아들은 롯의 아버지입니다. 여기서 하란(사람)과 31–32절에서 가족이 머문 하란(도시)은 서로 다른 존재입니다. 29–30절은 결혼 관계를 소개한 뒤 사래가 임신하지 못한다는 사실을 강조합니다. 12:2에서 하나님이 큰 민족을 약속하시기 전에, 그 약속이 인간의 능력만으로 실현될 수 없는 현실을 먼저 제시하는 것입니다.","31절은 데라 일행이 ‘가나안 땅으로 가려고’ 갈대아 우르를 떠났지만 하란에 이르러 거주했다고 말합니다. 출발지, 의도한 목적지, 실제 거주지가 구별됩니다. 본문은 왜 그곳에 머물렀는지 설명하지 않습니다. 데라가 두려워했거나 불순종했거나 병들었기 때문이라고 확정할 수 없습니다. 32절은 데라의 죽음으로 끝나고 12:1–3은 아브람을 향한 하나님의 말씀과 땅·자손·복의 약속으로 시작됩니다. 인간이 자기 이름을 만들려던 바벨의 이야기와 달리, 12:2에서는 하나님이 아브람의 이름을 크게 하겠다고 말씀하십니다. 이 대조는 흩어짐과 약속의 전환을 이해하는 중요한 문학적 열쇠입니다.","우르의 위치를 둘러싼 여러 견해와 하란의 지리적 역할은 별도의 ‘우르에서 하란으로’ 여정 연구에서 더 깊이 다룰 수 있습니다. 창세기 11장 자체가 분명하게 알려 주는 것은 출발지, 목적지, 실제 머문 곳이며, 구체적인 통과 지점이나 가족이 하란에 머문 이유는 설명하지 않는다는 사실입니다. 이 장을 읽을 때는 미확정 경로보다 하나님의 약속이 들어올 가족의 현실에 주목하는 것이 중요합니다."]}],"discoveries":[{"id":"gen11-deep-0","domain":"theology","title":"더 깊은 연구","paragraphs":["11:1–9는 건축 기술에 대한 반대가 아니라 자기 이름과 안정된 통제를 절대화한 집단적 계획을 드러냅니다. ‘한 언어’와 10장의 ‘여러 언어’의 관계는 시간 재배열과 공통 교역 언어라는 해석 가능성을 구별해야 합니다. 시날의 지리적 범위, 특정 탑의 고고학적 동일시, 이동 방향, 11:6의 하나님의 말씀의 정확한 함의는 확정적 세부가 아닙니다. 11:10–26의 족보 연령 차이는 실제 본문 전승의 문제로 보존해야 합니다."]},{"id":"gen11-deep-1","domain":"theology","title":"심화 설명","paragraphs":["사도행전 2:5–11에서 사람들은 서로 다른 언어를 유지하면서도 하나님의 큰일을 알아듣습니다. 따라서 오순절을 바벨 이전의 단일 언어로 돌아간 사건이라고 설명하는 것은 부정확합니다. 오히려 언어의 다양성 가운데 복음이 전달되는 정경적 대비입니다. 창세기 12:1–3은 하나님이 아브람을 통해 땅의 모든 족속에게 복을 주겠다는 약속을 제시하여 10장의 민족 세계와 11장의 한 가족을 연결합니다. 여호수아 24:2–3은 강 저편 조상들의 종교적 환경과 하나님의 주도적 인도를 회고합니다. 사도행전 7:2–4는 아브람의 부르심이 하란 이전 메소포타미아에서 시작되었다고 전하므로 창세기 11–12장의 시간 순서를 지나치게 단순화하지 않도록 돕습니다. 히브리서 11:8–10은 아브라함의 여정을 약속에 대한 믿음과 아직 완성되지 않은 소망의 관점에서 읽습니다."]},{"id":"gen11-deep-2","domain":"theology","title":"심화 설명","paragraphs":["중심 메시지: 인간은 자기 이름과 안전을 확보하기 위해 한곳에 집중하지만 하나님은 그 계획을 흩으시고, 여러 민족 가운데 한 가족을 통해 새 약속의 역사를 시작하십니다. 이야기의 중심은 인간이 만들어 낸 영광이 아니라 아직 자녀도 땅도 확보하지 못한 사람들에게 먼저 말씀하시는 하나님입니다."]},{"id":"gen11-deep-3","domain":"theology","title":"심화 설명","paragraphs":["---"]}],"lexicalCards":[{"verse":1,"form":"שָׂפָה אֶחָת","lemma":"שָׂפָה אֶחָת","transliteration":"","pronunciation":"사파 에하트","gloss":"한 언어·한 입술","morphology":"본문 문맥","note":"‘한 입술/한 언어’가 공통 소통의 조건을 제시합니다."},{"verse":4,"form":"שֵׁם","lemma":"שֵׁם","transliteration":"","pronunciation":"셈","gloss":"이름","morphology":"본문 문맥","note":"자기 이름을 만들려는 의도와 도시·탑의 역할. 12:2와 대비합니다."},{"verse":5,"form":"יָרַד","lemma":"יָרַד","transliteration":"","pronunciation":"야라드","gloss":"내려오다","morphology":"본문 문맥","note":"‘내려오다’가 인간의 높아짐을 문학적으로 상대화합니다."},{"verse":7,"form":"בָּלַל","lemma":"בָּלַל","transliteration":"","pronunciation":"발랄","gloss":"뒤섞다·혼잡하게 하다","morphology":"본문 문맥","note":"언어의 혼잡과 사람의 흩어짐. 바벨 명칭과는 히브리어 언어유희입니다."},{"verse":10,"form":"תּוֹלְדֹת","lemma":"תּוֹלְדֹת","transliteration":"","pronunciation":"톨레도트","gloss":"계보·족보","morphology":"본문 문맥","note":"넓은 세계에서 셈의 직계, 다시 데라의 가족으로 초점을 좁힙니다."},{"verse":30,"form":"עֲקָרָה","lemma":"עֲקָרָה","transliteration":"","pronunciation":"아카라","gloss":"아이를 낳지 못하는 여자","morphology":"본문 문맥","note":"사래의 불임이 12장의 후손 약속과 긴장을 만듭니다."}],"cautions":["10장의 언어 분화와 11장의 한 언어를 단순 시간순으로만 해석하지 않습니다.","바벨 언어유희와 실제 도시명의 어원을 혼동하지 않습니다.","셈 계보의 본문 전승별 연대를 하나의 절대연대로 단정하지 않습니다.","우르–하란 여정의 정확한 경로와 장소 ID는 미확정입니다."],"canonicalLinks":[{"ref":"신 1:28","note":"탑 높이의 문구를 문자적 우주 도달 계획으로만 읽지 않게 합니다."},{"ref":"행 2:5–11","note":"바벨의 소통 붕괴와 대비되지만 단일 언어로의 복귀는 아닙니다."},{"ref":"창 12:1–3","note":"인간이 자기 이름을 만들려는 도시에서 하나님이 이름을 주시는 약속으로 초점이 이동합니다."},{"ref":"수 24:2–3; 행 7:2–4","note":"이동의 원인을 데라의 심리로 발명하지 않고 하나님의 주도적 선택을 읽게 합니다."},{"ref":"히 11:8–10","note":"우르·하란의 미완성 여정에 후대 정경적 신뢰의 의미를 더합니다."}]}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("gen");})(window);
